  X         : REAL := 0;
  /// Position of the center of gravity relative to the flange.
  /// Y value [mm]  
  Y         : REAL := 0;
  /// Position of the center of gravity relative to the flange.
  /// Z value [mm]  
  Z         : REAL := 0;
