FUNCTION IsDefaultDynamicsEqual : BOOL
// ------------------------------------------------------------------------- 
//  SRCI Robot Library                                                
// ------------------------------------------------------------------------- 
//                                                                           
//  Object:      IsDefaultDynamicsEqual                                       
//  Author:      Thorsten Brach                                                
//  Date:        2025-04-23
//
//  Description:                                              
//   
//                                                                           
//  Copyright: 
//    (C) 2025 Thorsten Brach. All rights reserved                                                                                                                                            
//             Licensed under the MIT License.
//                                                                           
//  Disclaimer:                                                                           
//    This project is provided without any guarantee and can be used for   
//    private and commercial purposes. Any use is at the user’s 
//    own risk and responsibility.
//
// -------------------------------------------------------------------------
VAR_INPUT
  /// DefaultDynamics 1 to compare
  Data1           : DefaultDynamics;
  /// DefaultDynamics 2 to compare
  Data2           : DefaultDynamics;
  /// Flag to ignore the timestamp during the comparison
  IgnoreTimestamp : BOOL;
END_VAR

ST.xhtml:
IF (IgnoreTimestamp)
THEN
  Data1.Timestamp := Data2.Timestamp;
END_IF                    

IsDefaultDynamicsEqual := ( SysDepMemCmp( pData1 := ADR(Data1), pData2 :=  ADR(Data2), DataLen := SIZEOF(Data1)) = RobotLibraryConstants.OK );

