BytesToRCSupportedFunctions.ReadAnalogOutput           := Bytes[11].5;
// Byte 11 - Bit 6
BytesToRCSupportedFunctions.WriteAnalogOutput          := Bytes[11].6;
// Byte 11 - Bit 7
BytesToRCSupportedFunctions.MeasuringInput             := Bytes[11].7;

