OnExecCancel := Reset();
// Create log entry CreateLogMessagePara1 ( Timestamp := AxesGroup.State.SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := 'Execution of {1} cancled ', Para1 := MyType);
// try to remove cmd _retVal := AxesGroup.Acyclic.ActiveCommandRegister.RemoveCmd(_uniqueID);
IF (_retVal = RobotLibraryConstants.OK) THEN // Create log entry CreateLogMessagePara1 ( Timestamp := AxesGroup.State.SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := '{1} successfully removed from ACR', Para1 := MyType); ELSE // Create log entry CreateLogMessagePara1 ( Timestamp := AxesGroup.State.SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := '{1} was not removed from ACR because execution was already in progress', Para1 := MyType); END_IF

