/// returns a datablock from the payload buffer from the current payload pointer address and increase the payload pointer afterwards
METHOD GetDataBlock
VAR_INPUT
  /// Target
  pData    : POINTER TO BYTE;
  /// Size of data block
  Size     : UDINT;
  /// Target data type is string ? 
  IsString : BOOL;
END_VAR

ST.xhtml:
// update internal pointer
UpdatePointer();

// check pointer is valid ? 
IF (pPayload = RobotLibraryConstants.NULL_POINTER)
THEN
  RETURN;
END_IF


IF ( pData <> RobotLibraryConstants.NULL_POINTER)
THEN
  IF ( IsString)
  THEN
    Size := Size -1;
  END_IF

  // copy data (ST-FIX F22: only the bytes that are in the buffer, the rest is 0)
  SysDepMemSet(pDest := pData, Value := 0, DataLen := Size);
  IF ( PayloadPtr >= 0 ) AND ( DINT_TO_UDINT(PayloadPtr) < _payloadSize )
  THEN
    SysDepMemCpy(pDest   := pData,
                 pSrc    := pPayload + DINT_TO_DWORD(PayloadPtr),
                 DataLen := MIN(Size, _payloadSize - DINT_TO_UDINT(PayloadPtr)));
  END_IF

  // inc payload pointer 
  PayloadPtr := PayloadPtr + UDINT_TO_DINT(Size);
END_IF

