VAR_INPUT
  /// Reference to BaseFB 
  Caller       : REFERENCE TO RobotLibraryBaseFB;
  /// Current System Time
  SystemTime   : SystemTime;
  /// Index of the robot work area
  /// • 0 (default)..254
