METHOD PROTECTED CheckFunctionSupported : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

ST.xhtml:
CheckFunctionSupported := AxesGroup.State.RobotData.RCSupportedFunctions.CollisionDetection;

IF ( NOT CheckFunctionSupported )
THEN
  // call base implementation for set error and create log entry
  SUPER^.CheckFunctionSupported(AxesGroup := AxesGroup);
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED CheckFunctionSupported : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

METHOD PROTECTED CheckParameterChanged : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup    : AxesGroup; 
END_VAR

ST.xhtml:
// Check ParCmd Size is > 0, because MemCmp does not work correctly with size = 0
IF (SIZEOF(ParCmd) = 0) OR (_stepCmd = 0)
THEN 
  RETURN;
END_IF

// compare memory 
_parameterChanged := ( SysDepMemCmp(pData1 := ADR(ParCmd), pData2 := ADR(_parCmd), DataLen := SIZEOF(ParCmd)) <> RobotLibraryConstants.OK );

// check parameter valid ?
_parameterValid   := CheckParameterValid( AxesGroup := AxesGroup );

IF ((  _parameterChanged        )  AND 
    (  _parameterValid          )) OR
    (  _parameterUpdateInternal )  
THEN  
  // Create log entry for parameter changed event
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.DEBUG,
                          MessageCode := 0,
                          MessageText := 'NotifyParameterChanged Event {1}',
                          Para1       :=  '' );

  // reset internal flag for send parameter update
 _parameterUpdateInternal := FALSE;
  // update internal copy of parameters 
 _parCmd := ParCmd;
  // inc parameter sequence
 _command.ParSeq := _command.ParSeq + 1;
  // update command data  
  CommandData := CreateCommandPayload(AxesGroup := AxesGroup); // ( Access via reference to rCommandFB in ACR )
  // notify active command register 
  AxesGroup.Acyclic.ActiveCommandRegister.NotifyParameterChanged := _uniqueID;
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED CheckParameterChanged : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup    : AxesGroup; 
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

ST.xhtml:
                  CheckParameterValid := TRUE;

// Check ParCmd.ProcessingMode defined ? 
IF (( ProcessingMode < ProcessingModeEnum.BUFFERED         ) OR // ST-FIX F26
    ( ProcessingMode > ProcessingModeEnum.TRIGGER_MULTIPLE ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_DEFINED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;                          
END_IF

// Check ProcessingMode valid ? 
IF (( ProcessingMode <> ProcessingModeEnum.BUFFERED ) AND
    ( ProcessingMode <> ProcessingModeEnum.ABORTING ) AND  
    ( ProcessingMode <> ProcessingModeEnum.PARALLEL ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;                          
END_IF

// Check SequenceFlag valid ? 
IF (( SequenceFlag <> SequenceFlagEnum.NO_SEQUENCE        ) AND // ST-FIX F69: default with Parallel
    ( SequenceFlag <> SequenceFlagEnum.PRIMARY_SEQUENCE   ) AND
    ( SequenceFlag <> SequenceFlagEnum.SECONDARY_SEQUENCE ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_SEQFLAG_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter SequenceFlag = {1}',
                          Para1       := SEQUENCE_FLAG_TO_STRING(SequenceFlag));
  RETURN;                          
END_IF


// Check ParCmd.ReactionMode valid ? 
IF (( ParCmd.ReactionMode < CollisionReactionMode.STANDING_STILL    ) OR  
    ( ParCmd.ReactionMode > CollisionReactionMode.REVERSED_MOVEMENT ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE ); 
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ReactionMode = {1}',
                          Para1       :=  COLLISION_REACTION_MODE_TO_STRING(ParCmd.ReactionMode));
  RETURN;                          
END_IF


// Check ParCmd.ThresholdMode valid ? 
IF (( ParCmd.ThresholdMode <> ThresholdMode.AUTOMATIC ) AND  
    ( ParCmd.ThresholdMode <> ThresholdMode.MANUAL    ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ThresholdMode = {1}',
                          Para1       := THRESHOLD_MODE_TO_STRING(ParCmd.ThresholdMode));
  RETURN;                          
END_IF



// Check ParCmd.Sensitivity valid ? 
IF (( SysDepIsValidReal(ParCmd.Sensitivity) = FALSE ) OR
    ( ParCmd.Sensitivity                    <     0 ) OR  
    ( ParCmd.Sensitivity                    >   200 ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.Sensitivity = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.Sensitivity));
  RETURN;                          
END_IF



FOR _idx := 0 TO 6
DO
  // Check ParCmd.SensitivityAxis valid ? 
  IF (( SysDepIsValidReal(ParCmd.SensitivityAxis[_idx]) = FALSE ) OR
      (                   ParCmd.SensitivityAxis[_idx]  <     0 ) OR  
      (                   ParCmd.SensitivityAxis[_idx]  >   200 ))      
  THEN
    // Parameter not valid
    CheckParameterValid := FALSE;
    // Set error
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE ); 
    // Create log entry
    CreateLogMessagePara2 ( Timestamp   := AxesGroup.State.SystemTime,
                            MessageType := MessageType.CMD,
                            Severity    := Severity.ERROR,
                            MessageCode := ErrorID,
                            MessageText := 'Invalid Parameter ParCmd.SensitivityAxis[{2}] = {1}',
                            Para1       := VALID_REAL_TO_STRING(ParCmd.SensitivityAxis[_idx]),
                            Para2       := DINT_TO_STRING(_idx));
    EXIT;
    RETURN;                          
  END_IF
END_FOR  


FOR _idx := 0 TO 6
DO
  // Check ParCmd.LimitAxis valid ? 
  IF (( SysDepIsValidReal(ParCmd.LimitAxis[_idx]) = FALSE ))
  THEN
    // Parameter not valid
    CheckParameterValid := FALSE;
    // Set error
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE ); 
    // Create log entry
    CreateLogMessagePara2 ( Timestamp   := AxesGroup.State.SystemTime,
                            MessageType := MessageType.CMD,
                            Severity    := Severity.ERROR,
                            MessageCode := ErrorID,
                            MessageText := 'Invalid Parameter ParCmd.LimitAxis[{2}] = {1}',
                            Para1       := VALID_REAL_TO_STRING(ParCmd.LimitAxis[_idx]),
                            Para2       := DINT_TO_STRING(_idx));
    EXIT;
    RETURN;                          
  END_IF
END_FOR  


// Check ParCmd.UnitLimitAxis valid ? 
IF (( ParCmd.UnitLimitAxis <> UnitLimitAxis.PERCENTAGE  ) AND  
    ( ParCmd.UnitLimitAxis <> UnitLimitAxis.NEWTONMETER ) AND
    ( ParCmd.UnitLimitAxis <> UnitLimitAxis.MILLIAMPERE ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.UnitLimitAxis = {1}',
                          Para1       := THRESHOLD_MODE_TO_STRING(ParCmd.UnitLimitAxis));
  RETURN;                          
END_IF

// ST-FIX F69: trigger IDs and SequenceFlag (table 7-1, 5.5.12.4, e.g. table 6-496)
// ST-FIX F83: not for DEACTIVATE (it is sent with the SequenceFlag of the command it ends)
IF ( CheckParameterValid ) AND ( ProcessingMode <> ProcessingModeEnum.DEACTIVATE ) AND ( ( (( ProcessingMode = ProcessingModeEnum.BUFFERED ) OR ( ProcessingMode = ProcessingModeEnum.ABORTING ) OR ( ProcessingMode = ProcessingModeEnum.TRIGGER_BUFFERED ) OR ( ProcessingMode = ProcessingModeEnum.TRIGGER_ABORTING )) ) = ( SequenceFlag = SequenceFlagEnum.NO_SEQUENCE ) )
THEN
  CheckParameterValid := FALSE;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_SEQFLAG_INVALID_IN_PROC_MODE, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara2 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter SequenceFlag = {1} with ProcessingMode = {2}',
                          Para1       := SEQUENCE_FLAG_TO_STRING(SequenceFlag),
                          Para2       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;
END_IF

// ST-FIX F49: ParCmd.ProcessingMode was not checked
IF ( ( ParCmd.ProcessingMode <> ProcessingModeEnum.BUFFERED ) AND
    ( ParCmd.ProcessingMode <> ProcessingModeEnum.ABORTING ) AND
    ( ParCmd.ProcessingMode <> ProcessingModeEnum.PARALLEL ) AND
    ( ParCmd.ProcessingMode <> ProcessingModeEnum.CONTINUOUS ) AND
    ( ParCmd.ProcessingMode <> ProcessingModeEnum.DEACTIVATE ) AND
    ( ParCmd.ProcessingMode <> ProcessingModeEnum.TRIGGER_BUFFERED ) AND
    ( ParCmd.ProcessingMode <> ProcessingModeEnum.TRIGGER_ABORTING ) AND
    ( ParCmd.ProcessingMode <> ProcessingModeEnum.TRIGGER_ONCE ) AND
    ( ParCmd.ProcessingMode <> ProcessingModeEnum.TRIGGER_CONTINUOUS ) AND
    ( ParCmd.ProcessingMode <> ProcessingModeEnum.TRIGGER_MULTIPLE ) )
THEN
  CheckParameterValid := FALSE;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_DEFINED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ParCmd.ProcessingMode));
  RETURN;
END_IF

// ST-FIX F49: ParCmd.SequenceFlag was not checked
IF ( ( ParCmd.SequenceFlag <> SequenceFlagEnum.NO_SEQUENCE ) AND
    ( ParCmd.SequenceFlag <> SequenceFlagEnum.PRIMARY_SEQUENCE ) AND
    ( ParCmd.SequenceFlag <> SequenceFlagEnum.SECONDARY_SEQUENCE ) )
THEN
  CheckParameterValid := FALSE;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_SEQFLAG_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.SequenceFlag = {1}',
                          Para1       := SEQUENCE_FLAG_TO_STRING(ParCmd.SequenceFlag));
  RETURN;
END_IF

