THEN
  // Reset command outputs
  SysDepMemSet(pDest := ADR(OutCmd), Value := 0, DataLen := SIZEOF(OutCmd));         
END_IF

IF ( State = CmdMessageState.ACTIVE ) OR ( State = CmdMessageState.DONE ) // ST-FIX F42
THEN
  // Update results
  OutCmd.Enabled                          := _response.Enabled.0;
  OutCmd.RobotAxesBrakeReleased.Bit00     := _response.RobotAxesBrakeReleased.0;
  OutCmd.RobotAxesBrakeReleased.AxisJ1    := _response.RobotAxesBrakeReleased.1;
  OutCmd.RobotAxesBrakeReleased.AxisJ2    := _response.RobotAxesBrakeReleased.2;
  OutCmd.RobotAxesBrakeReleased.AxisJ3    := _response.RobotAxesBrakeReleased.3;
  OutCmd.RobotAxesBrakeReleased.AxisJ4    := _response.RobotAxesBrakeReleased.4;
  OutCmd.RobotAxesBrakeReleased.AxisJ5    := _response.RobotAxesBrakeReleased.5;
  OutCmd.RobotAxesBrakeReleased.AxisJ6    := _response.RobotAxesBrakeReleased.6;
  OutCmd.RobotAxesBrakeReleased.Bit07     := _response.RobotAxesBrakeReleased.7;
  OutCmd.ExternalAxesBrakeReleased.Bit00  := _response.ExternalAxesBrakeReleased.0;
  OutCmd.ExternalAxesBrakeReleased.AxisE1 := _response.ExternalAxesBrakeReleased.1;
  OutCmd.ExternalAxesBrakeReleased.AxisE2 := _response.ExternalAxesBrakeReleased.2;
  OutCmd.ExternalAxesBrakeReleased.AxisE3 := _response.ExternalAxesBrakeReleased.3;
  OutCmd.ExternalAxesBrakeReleased.AxisE4 := _response.ExternalAxesBrakeReleased.4;
  OutCmd.ExternalAxesBrakeReleased.AxisE5 := _response.ExternalAxesBrakeReleased.5;
  OutCmd.ExternalAxesBrakeReleased.AxisE6 := _response.ExternalAxesBrakeReleased.6;
  OutCmd.ExternalAxesBrakeReleased.Bit07  := _response.ExternalAxesBrakeReleased.7;
END_IF

// ST-FIX F42: output Enabled of the enable block
Enabled := OutCmd.Enabled;

InterfaceAsPlainText.xhtml:
                METHOD PROTECTED OnApplyOutCmd
VAR_INPUT
  /// Command message state
  State : CmdMessageState;
END_VAR

                METHOD Protected OnExecCancel : DINT
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal return value 
 _retVal    : DINT;
END_VAR

                METHOD Protected OnExecCancel : DINT
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal return value 
 _retVal    : DINT;
END_VAR

ST.xhtml:
                  OnExecCancel := RobotLibraryConstants.RUNNING;

CASE _stepCancel OF

  0: // set busy flag
     Busy := TRUE;

     // Create log entry
     CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                             MessageType := MessageType.CMD,
                             Severity    := Severity.DEBUG,
                             MessageCode := 0,
                             MessageText := 'Execution of {1} cancelled',
                             Para1       := MyType);                 

     // try to remove cmd
    _retVal := AxesGroup.Acyclic.ActiveCommandRegister.RemoveCmd(_uniqueID);

     // check result of removement       
     IF ( _retVal = RobotLibraryConstants.OK )
     THEN
       // Reset step counter
      _stepCancel := 0;
       // finished okay
       OnExecCancel := RobotLibraryConstants.OK;

       // Create log entry
       CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                               MessageType := MessageType.CMD,
                               Severity    := Severity.DEBUG,
                               MessageCode := 0,
                               MessageText := '{1} successfully removed from ACR',
                               Para1       := MyType);                 
     ELSE
       // set timeout
       SetTimeout(PT := _timeoutCancel, rTimer := _timerCancel);
       // inc step counter
      _stepCancel := _stepCancel + 1; 

       // Create log entry
       CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                               MessageType := MessageType.CMD,
                               Severity    := Severity.DEBUG,
                               MessageCode := 0,
                               MessageText := '{1} was not removed from ACR because execution was already in progress',
                               Para1       := MyType);                 
     END_IF       


 1:  // call clear error 
     OnExecCancel := OnExecErrorClear(AxesGroup := AxesGroup);  

     IF ( OnExecCancel = RobotLibraryConstants.OK)
     THEN
       // Reset busy flag
       Busy := FALSE;
       // Reset step counter
      _stepCancel := 0;
       // finished okay
       OnExecCancel := RobotLibraryConstants.OK;
     END_IF  

ELSE
  // invalid step
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_STEP, Overwrite := TRUE );
END_CASE  



// reset step counter
IF (OnExecCancel <> RobotLibraryConstants.RUNNING)
THEN
  // Reset FB variables
  Reset();
  // Reset step counter
 _stepCancel := 0;
END_IF

