           Reset();
           // set busy flag
           Busy := TRUE;
           // Reset command outputs
           SysDepMemSet(pDest := ADR(OutCmd), Value := 0, DataLen := SIZEOF(OutCmd));         
           // apply command parameter
          _parCmd := ParCmd;
           // Create logging
           CreateCommandParameterLog(AxesGroup := AxesGroup);  
           // set timeout
           SetTimeout(PT := _timeoutCmd, rTimer := _timerCmd);
           // inc step counter
          _stepCmd := _stepCmd + 1; 
         END_IF 
       END_IF


  01:  // Wait for FrameNo and ToolNo set
       IF (AxesGroup.CyclicOptional.RobToPlc.SubProgramData.Active) 
       THEN
         // busy 
         Busy := FALSE;
         // reset busy flag
         Enabled := TRUE;          
         // Reset command outputs
         SysDepMemSet(pDest := ADR(OutCmd), Value := 0, DataLen := SIZEOF(OutCmd));         
         // update command outputs
         OutCmd.Data := AxesGroup.CyclicOptional.RobToPlc.SubProgramData.Data;
       END_IF

       IF ( _enable_F.Q)
       THEN
         // reset the falling edge
        _enable_F();       
         // set timeout
         SetTimeout(PT := _timeoutCmd, rTimer := _timerCmd);
         // inc step counter
        _stepCmd := _stepCmd + 1; 
       END_IF

  02:  IF (NOT Enable)
       THEN
         Reset();  
       END_IF

ELSE
  // invalid step
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_STEP, Overwrite := TRUE );
END_CASE



// Reset FB
IF (( _enable_R.Q ) OR
    ( _enable_F.Q ))
THEN
  Reset();
END_IF

