METHOD PROTECTED CheckFunctionSupported : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

ST.xhtml:
CheckFunctionSupported := AxesGroup.State.RobotData.RCSupportedFunctions.StopSubprogram;

IF ( NOT CheckFunctionSupported )
THEN
  // call base implementation for set error and create log entry
  SUPER^.CheckFunctionSupported(AxesGroup := AxesGroup);
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED CheckFunctionSupported : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

METHOD PROTECTED CheckParameterChanged : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup    : AxesGroup; 
END_VAR

ST.xhtml:
// Check ParCmd Size is > 0, because MemCmp does not work correctly with size = 0
IF (SIZEOF(ParCmd) = 0) OR (_stepCmd = 0)
THEN 
  RETURN;
END_IF

// compare memory 
_parameterChanged := ( SysDepMemCmp(pData1 := ADR(ParCmd), pData2 := ADR(_parCmd), DataLen := SIZEOF(ParCmd)) <> RobotLibraryConstants.OK );

// check parameter valid ?
_parameterValid   := CheckParameterValid( AxesGroup := AxesGroup );

IF ((  _parameterChanged        )  AND 
    (  _parameterValid          )) OR
    (  _parameterUpdateInternal )  
THEN  
  // Create log entry for parameter changed event
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.DEBUG,
                          MessageCode := 0,
                          MessageText := 'NotifyParameterChanged Event {1}',
                          Para1       :=  '' );

  // reset internal flag for send parameter update
 _parameterUpdateInternal := FALSE;
  // update internal copy of parameters 
 _parCmd := ParCmd;
  // inc parameter sequence
 _command.ParSeq := _command.ParSeq + 1;
  // update command data  
  CommandData := CreateCommandPayload(AxesGroup := AxesGroup); // ( Access via reference to rCommandFB in ACR )
  // notify active command register 
  AxesGroup.Acyclic.ActiveCommandRegister.NotifyParameterChanged := _uniqueID;
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED CheckParameterChanged : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup    : AxesGroup; 
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

ST.xhtml:
                  CheckParameterValid := TRUE;

// Check ParCmd.ProcessingMode defined ? 
IF (( ProcessingMode < ProcessingModeEnum.BUFFERED         ) OR // ST-FIX F26
    ( ProcessingMode > ProcessingModeEnum.TRIGGER_MULTIPLE ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_DEFINED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;                          
END_IF

// Check ProcessingMode valid ? 
IF (( ProcessingMode <> ProcessingModeEnum.BUFFERED           ) AND
    ( ProcessingMode <> ProcessingModeEnum.ABORTING           ) AND  
    ( ProcessingMode <> ProcessingModeEnum.PARALLEL           ) AND
    ( ProcessingMode <> ProcessingModeEnum.DEACTIVATE         ) AND
    ( ProcessingMode <> ProcessingModeEnum.TRIGGER_ONCE       ) AND
    ( ProcessingMode <> ProcessingModeEnum.TRIGGER_MULTIPLE   )) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;                          
END_IF

// Check SequenceFlag valid ? 
IF (( SequenceFlag <> SequenceFlagEnum.NO_SEQUENCE        ) AND    
    ( SequenceFlag <> SequenceFlagEnum.PRIMARY_SEQUENCE   ) AND
    ( SequenceFlag <> SequenceFlagEnum.SECONDARY_SEQUENCE ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_SEQFLAG_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter SequenceFlag = {1}',
                          Para1       := SEQUENCE_FLAG_TO_STRING(SequenceFlag));
  RETURN;                          
END_IF


// Check ParCmd.StopMode valid ? 
IF (( ParCmd.StopMode <> StopMode.STOP_JOB_ID          ) AND  
    ( ParCmd.StopMode <> StopMode.STOP_INSTANCE_ID     ) AND
    ( ParCmd.StopMode <> StopMode.STOP_ALL_SUBPROGRAMS ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.StopMode = {1}',
                          Para1       :=  STOP_MODE_TO_STRING(ParCmd.StopMode));
  RETURN;                          
END_IF


// Check ParCmd.TargetID valid ? 
IF (( ParCmd.TargetID <  -1 ) OR 
    ( ParCmd.TargetID > 65534 )) // ST-FIX F88: UINT in the telegram, 65535 = -1
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.TargetID = {1}',
                          Para1       := DINT_TO_STRING(ParCmd.TargetID));                            
  RETURN;
END_IF


// Check ParCmd.ListenerID valid ? 
IF (( ParCmd.ListenerID <   0 ) OR 
    ( ParCmd.ListenerID > 127 ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_LISTENERID_MUST_BE_POSITIVE, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ListenerID = {1}',
                          Para1       := SINT_TO_STRING(ParCmd.ListenerID));                            
  RETURN;
END_IF

// ST-FIX F69: trigger IDs and SequenceFlag (table 7-1, 5.5.12.4, e.g. table 6-496)
IF ( CheckParameterValid ) AND (( ParCmd.EmitterID[0] < -127 ) OR ( ParCmd.EmitterID[1] < -127 ) OR ( ParCmd.EmitterID[2] < -127 ) OR ( ParCmd.EmitterID[3] < -127 ))
THEN
  CheckParameterValid := FALSE;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_EMITTERID_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessage ( Timestamp   := AxesGroup.State.SystemTime,
                     MessageType := MessageType.CMD,
                     Severity    := Severity.ERROR,
                     MessageCode := ErrorID,
                     MessageText := 'Invalid Parameter ParCmd.EmitterID (< -127)');
  RETURN;
END_IF
IF ( CheckParameterValid ) AND ( ProcessingMode >= ProcessingModeEnum.TRIGGER_BUFFERED ) AND ( ParCmd.ListenerID = 0 )
THEN
  CheckParameterValid := FALSE;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_LISTENERID_MUST_BE_GREATER_THAN_ZERO, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ListenerID = 0 with ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;
END_IF
IF ( CheckParameterValid ) AND ( ProcessingMode <> ProcessingModeEnum.DEACTIVATE ) AND NOT ( ProcessingMode >= ProcessingModeEnum.TRIGGER_BUFFERED ) AND ( ParCmd.ListenerID > 0 )
THEN
  CheckParameterValid := FALSE;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_LISTENERID_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ListenerID <> 0 with ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;
END_IF
// ST-FIX F83: not for DEACTIVATE (it is sent with the SequenceFlag of the command it ends)
IF ( CheckParameterValid ) AND ( ProcessingMode <> ProcessingModeEnum.DEACTIVATE ) AND ( ( (( ProcessingMode = ProcessingModeEnum.BUFFERED ) OR ( ProcessingMode = ProcessingModeEnum.ABORTING ) OR ( ProcessingMode = ProcessingModeEnum.TRIGGER_BUFFERED ) OR ( ProcessingMode = ProcessingModeEnum.TRIGGER_ABORTING )) ) = ( SequenceFlag = SequenceFlagEnum.NO_SEQUENCE ) )
THEN
  CheckParameterValid := FALSE;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_SEQFLAG_INVALID_IN_PROC_MODE, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara2 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter SequenceFlag = {1} with ProcessingMode = {2}',
                          Para1       := SEQUENCE_FLAG_TO_STRING(SequenceFlag),
                          Para2       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;
END_IF

// ST-FIX F49: ParCmd.SequenceFlag was not checked
IF ( ( ParCmd.SequenceFlag <> SequenceFlagEnum.NO_SEQUENCE ) AND
    ( ParCmd.SequenceFlag <> SequenceFlagEnum.PRIMARY_SEQUENCE ) AND
    ( ParCmd.SequenceFlag <> SequenceFlagEnum.SECONDARY_SEQUENCE ) )
THEN
  CheckParameterValid := FALSE;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_SEQFLAG_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.SequenceFlag = {1}',
                          Para1       := SEQUENCE_FLAG_TO_STRING(ParCmd.SequenceFlag));
  RETURN;
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

METHOD INTERNAL CreateCommandPayload : RobotLibraryCommandDataFB
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx          : DINT;
  /// Parameter count
 _parameterCnt : DINT;
END_VAR
// Table 6-697: Sent CMD payload (PLC to RC) of "StopSubprogram"
// --------------------------
// Header
// --------------------------
// Byte 00 : UINT  - Type HB     
// Byte 01 :       - Type LB    
// Byte 02 : USINT - Reserve | ExecutionMode
// Byte 03 : USINT - ParSeq  | Priority
// --------------------------
// Datablock
// --------------------------
// Byte 04 : SINT  EmitterID[0];
// Byte 05 : SINT  EmitterID[1];
// Byte 06 : SINT  EmitterID[2];
// Byte 07 : SINT  EmitterID[3];
// Byte 08 : SINT  ListenerID;
// Byte 09 : BYTE  Reserved;
// Byte 10 : UINT  TargetID;
// Byte 11 :       TargetID;
// Byte 12 : USINT StopMode;

METHOD INTERNAL CreateCommandPayload : RobotLibraryCommandDataFB
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx          : DINT;
  /// Parameter count
 _parameterCnt : DINT;
END_VAR
// Table 6-697: Sent CMD payload (PLC to RC) of "StopSubprogram"
// --------------------------
// Header
// --------------------------
// Byte 00 : UINT  - Type HB     
// Byte 01 :       - Type LB    
// Byte 02 : USINT - Reserve | ExecutionMode
// Byte 03 : USINT - ParSeq  | Priority
// --------------------------
// Datablock
// --------------------------
// Byte 04 : SINT  EmitterID[0];
// Byte 05 : SINT  EmitterID[1];
// Byte 06 : SINT  EmitterID[2];
// Byte 07 : SINT  EmitterID[3];
// Byte 08 : SINT  ListenerID;
// Byte 09 : BYTE  Reserved;
// Byte 10 : UINT  TargetID;
// Byte 11 :       TargetID;
// Byte 12 : USINT StopMode;

ST.xhtml:
                  // set command parameter 
_command.CmdTyp     :=  CmdType.StopSubprogram;
// ST-FIX F51: ExecutionMode from ProcessingMode (and SequenceFlag), spec table 5-77
CASE ProcessingMode OF
  ProcessingModeEnum.BUFFERED, ProcessingModeEnum.TRIGGER_BUFFERED:
    IF ( SequenceFlag = SequenceFlagEnum.SECONDARY_SEQUENCE )
    THEN
      _command.ExecMode := ExecutionMode.SEQUENCE_SECONDARY;
    ELSE
      _command.ExecMode := ExecutionMode.SEQUENCE_PRIMARY;
    END_IF
  ProcessingModeEnum.ABORTING, ProcessingModeEnum.TRIGGER_ABORTING:
    IF ( SequenceFlag = SequenceFlagEnum.SECONDARY_SEQUENCE )
    THEN
      _command.ExecMode := ExecutionMode.SEQUENCE_ABORT_OTHERS_SECONDARY;
    ELSE
      _command.ExecMode := ExecutionMode.SEQUENCE_ABORT_OTHERS_PRIMARY;
    END_IF
  ProcessingModeEnum.PARALLEL, ProcessingModeEnum.TRIGGER_ONCE:
    _command.ExecMode := ExecutionMode.PARALLEL;
  ProcessingModeEnum.CONTINUOUS, ProcessingModeEnum.TRIGGER_CONTINUOUS:
    _command.ExecMode := ExecutionMode.CONTINUOUS;
  ProcessingModeEnum.TRIGGER_MULTIPLE:
    _command.ExecMode := ExecutionMode.TRIGGER_MULTIPLE;
  ProcessingModeEnum.DEACTIVATE:
    _command.ExecMode := ExecutionMode.STOP_PARALLEL_CONTINUOUS_TRIGGER;
ELSE
  // undefined ProcessingMode -> error, not sent (ST-FIX F49)
  _command.ExecMode := ExecMode;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_DEFINED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  OnUpdateStateFlags( State := CmdMessageState.ERROR );
END_CASE
_command.ParSeq     := _command.ParSeq;
_command.Priority   :=  Priority;
_command.EmitterID  := _parCmd.EmitterID;
_command.Reserve    := 0;
_command.ListenerID := _parCmd.ListenerID;
_command.Reserve    := 0;

IF (_parCmd.TargetID = -1)
THEN
  _command.TargetID   := 16#FFFF;
ELSE
  _command.TargetID   :=  DINT_TO_UINT(_parCmd.TargetID);
END_IF

_command.StopMode   := _parCmd.StopMode;

// copy command data to header
_cmdHeader := _command;
// call base implementation to copy header to payload buffer
CreateCommandPayload := SUPER^.CreateCommandPayload(AxesGroup := AxesGroup);


FOR _idx := 0 TO 3 
DO
  // Check parameter must be added ? 
  IF ( CheckAddParameter(CreateCommandPayload.PayloadPtr))
  THEN
    // add command.EmitterID[x]
    CreateCommandPayload.AddSint(_command.EmitterID[_idx]);
    // inc parameter counter
   _parameterCnt := _parameterCnt + 1;  
  END_IF
END_FOR


// Check parameter must be added ? 
IF ( CheckAddParameter(CreateCommandPayload.PayloadPtr))
THEN
  // add command.ListenerID
  CreateCommandPayload.AddSint(_command.ListenerID);
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;  
END_IF


// Check parameter must be added ? 
IF ( CheckAddParameter(CreateCommandPayload.PayloadPtr))
THEN
  // add command.Reserve
  CreateCommandPayload.AddByte(_command.Reserve);
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;  
END_IF


// Check parameter must be added ? 
IF ( CheckAddParameter(CreateCommandPayload.PayloadPtr))
THEN
  // add command.TargetID
  CreateCommandPayload.AddUint(_command.TargetID);
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;  
END_IF


// Check parameter must be added ? 
IF ( CheckAddParameter(CreateCommandPayload.PayloadPtr))
THEN
  // add command.StopMode
  CreateCommandPayload.AddUsint(_command.StopMode);
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;  
END_IF


// Create logging
CreateCommandPayloadLog(AxesGroup := AxesGroup, ParameterCnt := _parameterCnt);

