  /// Parameter which determines the behavior towards the previously sent and still active or buffered commands
  AbortingMode       : AbortingMode;
  /// Defines the target sequence in which the command will be executed
  SequenceFlag       : SequenceFlag;
  /// command parameter
  ParCmd             : MoveApproachLinearParCmd;     
END_VAR

VAR_OUTPUT
  /// Command is transferred and confirmed by the RC
  CommandBuffered    : BOOL;
  /// The command takes control of the motion of the according axis group
  Active             : BOOL;
  /// The command was aborted by another command.
  CommandAborted     : BOOL;
  /// TRUE, while command is interrupted during execution and can be continued
  CommandInterrupted : BOOL;
  /// command results
  OutCmd             : MoveApproachLinearOutCmd;     
END_VAR

VAR
  /// internal copy of command parameter 
 _parCmd             : MoveApproachLinearParCmd;
  /// command data to send
 _command            : MoveApproachLinearSendData;
  /// response data received
 _response           : MoveApproachLinearRecvData;      
END_VAR

METHOD INTERNAL CheckAddParameter : BOOL
VAR_INPUT
  /// Payload pointer
  PayloadPtr : UDINT;
END_VAR
VAR
  /// Payload as byte array
  Payload    : ARRAY [1..SIZEOF(_command)] OF BYTE;
  /// Null Byte array 
  Null       : ARRAY [1..SIZEOF(_command)] OF BYTE;
  /// Data length to compare
  DataLen    : UDINT;
END_VAR

METHOD INTERNAL CheckAddParameter : BOOL
VAR_INPUT
  /// Payload pointer
  PayloadPtr : UDINT;
END_VAR
VAR
  /// Payload as byte array
  Payload    : ARRAY [1..SIZEOF(_command)] OF BYTE;
  /// Null Byte array 
  Null       : ARRAY [1..SIZEOF(_command)] OF BYTE;
  /// Data length to compare
  DataLen    : UDINT;
END_VAR

ST.xhtml:
                  // Payload pointer must be decreased by one byte, because ADR(Payload) is already one byte !
PayloadPtr := LIMIT (0, PayloadPtr - 1, SIZEOF(Payload) -1);
// Convert command struct to payload array
SysDepMemCpy( pDest := ADR(Payload), pSrc := ADR(_command), DataLen := SIZEOF(_command));
// Calculate the data length to compare - at least one byte must be compared !
DataLen := LIMIT(1, SIZEOF(Payload) - PayloadPtr, SIZEOF(Payload)); 
// Compare Payload-Array with Null-Byte-Array
CheckAddParameter := SysDepMemCmp( pData1 := ADR(Payload) + PayloadPtr , pData2 := ADR(Null), DataLen := DataLen) <>  RobotLibraryConstants.OK ;

// ST-FIX F28: payload order differs from the structure layout -> always add the parameter
CheckAddParameter := TRUE;

InterfaceAsPlainText.xhtml:
METHOD INTERNAL CheckAddParameter : BOOL
VAR_INPUT
  /// Payload pointer
  PayloadPtr : UDINT;
END_VAR
VAR
  /// Payload as byte array
  Payload    : ARRAY [1..SIZEOF(_command)] OF BYTE;
  /// Null Byte array 
  Null       : ARRAY [1..SIZEOF(_command)] OF BYTE;
  /// Data length to compare
  DataLen    : UDINT;
END_VAR

METHOD PROTECTED CheckFunctionSupported : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

ST.xhtml:
CheckFunctionSupported := AxesGroup.State.RobotData.RCSupportedFunctions.MoveApproachLinear;

IF ( NOT CheckFunctionSupported )
THEN
  // call base implementation for set error and create log entry
  SUPER^.CheckFunctionSupported(AxesGroup := AxesGroup);
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED CheckFunctionSupported : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

METHOD PROTECTED CheckParameterChanged : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup    : AxesGroup; 
END_VAR

ST.xhtml:
// Check ParCmd Size is > 0, because MemCmp does not work correctly with size = 0
IF (SIZEOF(ParCmd) = 0) OR (_stepCmd = 0)
THEN 
  RETURN;
END_IF

// compare memory 
_parameterChanged := ( SysDepMemCmp(pData1 := ADR(ParCmd), pData2 := ADR(_parCmd), DataLen := SIZEOF(ParCmd)) <> RobotLibraryConstants.OK );

// check parameter valid ?
_parameterValid   := CheckParameterValid( AxesGroup := AxesGroup );

IF ((  _parameterChanged        )  AND 
    (  _parameterValid          )) OR
    (  _parameterUpdateInternal )  
THEN  
  // Create log entry for parameter changed event
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.DEBUG,
                          MessageCode := 0,
                          MessageText := 'NotifyParameterChanged Event {1}',
                          Para1       :=  '' );

  // reset internal flag for send parameter update
 _parameterUpdateInternal := FALSE;
  // update internal copy of parameters 
 _parCmd := ParCmd;
  // inc parameter sequence
 _command.ParSeq := _command.ParSeq + 1;
  // update command data  
  CommandData := CreateCommandPayload(AxesGroup := AxesGroup); // ( Access via reference to rCommandFB in ACR )
  // notify active command register 
  AxesGroup.Acyclic.ActiveCommandRegister.NotifyParameterChanged := _uniqueID;
END_IF

