  /// Parameter count
 _parameterCnt : DINT;
END_VAR
// Table 6-98: Sent CMD payload (PLC to RC) of "ChangeSpeedOverride"
// --------------------------
// Header
// --------------------------
// Byte 00 : UINT  - Type HB     
// Byte 01 :       - Type LB    
// Byte 02 : USINT - Reserve | ExecutionMode
// Byte 03 : USINT - ParSeq  | Priority
// --------------------------
// Datablock
// --------------------------
