 _idx          : DINT;
  /// Parameter count
 _parameterCnt : DINT;
END_VAR
// Table 6-254: Sent CMD payload (PLC to RC) of "MoveDirectAbsolute"
// --------------------------
// Header
// --------------------------
// Byte 00 : UINT  - Type HB     
