END_VAR

METHOD PROTECTED CheckFunctionSupported : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

ST.xhtml:
CheckFunctionSupported := AxesGroup.State.RobotData.RCSupportedFunctions.ReturnToPrimary;

IF ( NOT CheckFunctionSupported )
THEN
  // call base implementation for set error and create log entry
  SUPER^.CheckFunctionSupported(AxesGroup := AxesGroup);
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED CheckFunctionSupported : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

METHOD PROTECTED CheckParameterChanged : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup    : AxesGroup; 
END_VAR

ST.xhtml:
// Check ParCmd Size is > 0, because MemCmp does not work correctly with size = 0
IF (SIZEOF(ParCmd) = 0) OR (_stepCmd = 0)
THEN 
  RETURN;
END_IF

// compare memory 
_parameterChanged := ( SysDepMemCmp(pData1 := ADR(ParCmd), pData2 := ADR(_parCmd), DataLen := SIZEOF(ParCmd)) <> RobotLibraryConstants.OK );

// check parameter valid ?
_parameterValid   := CheckParameterValid( AxesGroup := AxesGroup );

IF ((  _parameterChanged        )  AND 
    (  _parameterValid          )) OR
    (  _parameterUpdateInternal )  
THEN  
  // Create log entry for parameter changed event
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.DEBUG,
                          MessageCode := 0,
                          MessageText := 'NotifyParameterChanged Event {1}',
                          Para1       :=  '' );

  // reset internal flag for send parameter update
 _parameterUpdateInternal := FALSE;
  // update internal copy of parameters 
 _parCmd := ParCmd;
  // inc parameter sequence
 _command.ParSeq := _command.ParSeq + 1;
  // update command data  
  CommandData := CreateCommandPayload(AxesGroup := AxesGroup); // ( Access via reference to rCommandFB in ACR )
  // notify active command register 
  AxesGroup.Acyclic.ActiveCommandRegister.NotifyParameterChanged := _uniqueID;
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED CheckParameterChanged : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup    : AxesGroup; 
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

ST.xhtml:
CheckParameterValid := TRUE;

// Check ParCmd.ReturnMode valid ? 
IF (( ParCmd.ReturnMode <> ReturnMode.INTERRUPT_POSITION ) AND   
    ( ParCmd.ReturnMode <> ReturnMode.END_POSITION       ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ReturnMode = {1}',
                          Para1       := RETURN_MODE_TO_STRING(ParCmd.ReturnMode));                            
  RETURN;
END_IF


// Check ParCmd.VelocityRate valid ? 
IF  (( SysDepIsValidReal(ParCmd.VelocityRate) = FALSE )  OR
    (* ST-FIX F96: every value < 0 is the default *)
     (                   ParCmd.VelocityRate  >   100 ))      
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_VELOCITY_INVALID, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.VelocityRate = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.VelocityRate));                            
  RETURN;
END_IF


// Check ParCmd.AccelerationRate valid ? 
IF  (( SysDepIsValidReal(ParCmd.AccelerationRate) = FALSE )  OR
    (* ST-FIX F96: every value < 0 is the default *)
     (                   ParCmd.AccelerationRate  >   100 ))      
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_ACCELERATION_INVALID, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.AccelerationRate = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.AccelerationRate));                            
  RETURN;
END_IF


// Check ParCmd.DecelerationRate valid ? 
IF  (( SysDepIsValidReal(ParCmd.DecelerationRate) = FALSE )  OR
    (* ST-FIX F96: every value < 0 is the default *)
     (                   ParCmd.DecelerationRate  >   100 ))      
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_DECELERATION_INVALID, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.DecelerationRate = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.DecelerationRate));                            
  RETURN;
END_IF


// Check ParCmd.JerkRate valid ? 
IF  (( SysDepIsValidReal(ParCmd.JerkRate) = FALSE )  OR
    (* ST-FIX F96: every value < 0 is the default *)
     (                   ParCmd.JerkRate  >   100 ))      
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_JERK_INVALID, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.JerkRate = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.JerkRate));                            
  RETURN;
END_IF


// Check ParCmd.ToolNo valid ? 
IF (( ParCmd.ToolNo <   0                                                ) OR   
    ( ParCmd.ToolNo > 254                                                ) OR
    ( ParCmd.ToolNo > AxesGroup.State.ConfigurationData.HighestToolIndex ) OR
    ( ParCmd.ToolNo > AxesGroup.State.UnifiedToolIndex                   ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;

  // Check ToolNo available on RC ? 
  IF (( ParCmd.ToolNo > AxesGroup.State.ConfigurationData.HighestToolIndex ) AND ( ParCmd.ToolNo <= 254 )) // ST-FIX F98: outside -1..254 is a range error
  THEN
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_TOOLNO_UNAVAILABLE, Overwrite := TRUE );
  ELSE
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_TOOLNO_RANGE, Overwrite := TRUE );
	END_IF  

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ToolNo = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.ToolNo));                            
  RETURN;
END_IF


// Check ParCmd.FrameNo valid ? 
IF (( ParCmd.FrameNo <   0                                                 ) OR   
    ( ParCmd.FrameNo > 254                                                 ) OR
    ( ParCmd.FrameNo > AxesGroup.State.ConfigurationData.HighestFrameIndex ) OR
    ( ParCmd.FrameNo > AxesGroup.State.UnifiedFrameIndex                   ))         
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;

  // Check FrameNo available on RC ? 
  IF (( ParCmd.FrameNo > AxesGroup.State.ConfigurationData.HighestFrameIndex ) AND ( ParCmd.FrameNo <= 254 )) // ST-FIX F98: outside -1..254 is a range error
  THEN
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_FRAMENO_UNAVAILABLE, Overwrite := TRUE );
  ELSE
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_FRAMENO_RANGE, Overwrite := TRUE );
	END_IF  

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.FrameNo = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.FrameNo));                            
  RETURN;
END_IF


// Check ParCmd.DistanceLimit valid ? 
IF  ( SysDepIsValidReal(ParCmd.DistanceLimit) = FALSE )
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_JERK_INVALID, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.DistanceLimit = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.DistanceLimit));                            
  RETURN;
END_IF


// Check ParCmd.TrajectoryMode valid ? 
IF ((* ST-FIX F99: INVALID (0) is not allowed *) ( ParCmd.TrajectoryMode <> TrajectoryMode.LINEAR_MOVEMENT ) AND
    ( ParCmd.TrajectoryMode <> TrajectoryMode.PTP_MOVEMENT    ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_TRAJECTORYMODE_INVALID, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.TrajectoryMode = {1}',
                          Para1       := TRAJECTORY_MODE_TO_STRING(ParCmd.TrajectoryMode));                            
  RETURN;
END_IF


// Check ParCmd.MoveTime valid ? 
IF  ( ParCmd.MoveTime < T#0S )
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.MoveTime = {1}',
                          Para1       := TIME_TO_STRING(ParCmd.MoveTime));                            
  RETURN;
END_IF


// Check ParCmd.AllowDifferences
// -> no plausibility check for boolean

