ST.xhtml:
MyType := 'MC_ReturnToPrimaryFB';

ExecMode := ExecutionMode.SEQUENCE_PRIMARY;
Priority := PriorityLevel.NORMAL;

InterfaceAsPlainText.xhtml:
METHOD FB_init : BOOL
VAR_INPUT
  /// if TRUE, the retain variables are initialized (warm start / cold start)
  bInitRetains : BOOL; 
  /// if TRUE, the instance afterwards gets moved into the copy code (online change)
  bInCopyCode  : BOOL;  
END_VAR

METHOD PROTECTED OnApplyOutCmd
VAR_INPUT
  /// Command message state
  State : CmdMessageState;
END_VAR

ST.xhtml:
IF ( State = CmdMessageState.EMPTY ) 
THEN
  // Reset command outputs
  SysDepMemSet(pDest := ADR(OutCmd), Value := 0, DataLen := SIZEOF(OutCmd));         
END_IF

IF (( State = CmdMessageState.ACTIVE ) OR
    ( State = CmdMessageState.DONE   ))
THEN
  // Update results
  OutCmd.Progress          :=  PERCENT_UINT_TO_REAL( Value := _response.Progress, IsOptional := TRUE);
  OutCmd.RemainingDistance := _response.RemainingDistance;
  OutCmd.PrimaryPosToolNo  := UINT_TO_USINT(_response.PrimaryPosToolNo);  {warning 'ToDo'}
  OutCmd.PrimaryPosFrameNo := UINT_TO_USINT(_response.PrimaryPosFrameNo); {warning 'ToDo'}
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED OnApplyOutCmd
VAR_INPUT
  /// Command message state
  State : CmdMessageState;
END_VAR

METHOD PROTECTED OnExecRun : DINT
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

ST.xhtml:
// call base implementation
SUPER^.OnExecRun(AxesGroup := AxesGroup);

// building rising and falling edges
_enable_R( CLK := Enable);
_enable_F( CLK := Enable);

CASE _stepCmd OF

  00:  IF ( _enable_R.Q ) AND ( NOT Error)  
       THEN
         // reset the rising edge
        _enable_R();       
         // reset the falling edge
        _enable_F();   

         // ST-FIX F77: commands not enabled (RobotTask not initialized) -> error like the Execute/Enable blocks
         IF ( NOT AxesGroup.State.CMDsEnabled )
         THEN
           SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_COMMANDS_NOT_ENABLED, Overwrite := TRUE );
           // Create log entry
           CreateLogMessage ( Timestamp   := AxesGroup.State.SystemTime,
                              MessageType := MessageType.CMD,
                              Severity    := Severity.ERROR,
                              MessageCode := ErrorID,
                              MessageText := 'Commands not enabled (RobotTask not initialized)');
           Error := TRUE;
         // Check function is supported and parameter are valid ?
         ELSIF (( CheckFunctionSupported( AxesGroup := AxesGroup )) AND
             ( CheckParameterValid   ( AxesGroup := AxesGroup )))      
         THEN
           // set busy flag
           Busy := TRUE;
           // Reset command outputs
           SysDepMemSet(pDest := ADR(OutCmd), Value := 0, DataLen := SIZEOF(OutCmd));         
           // apply command parameter
          _parCmd := ParCmd;
           // init parameter sequence
          _command.ParSeq := 1;
           // create command data
           CommandData := CreateCommandPayload(AxesGroup := AxesGroup);
           // Add command to active command register
          _uniqueID := AxesGroup.Acyclic.ActiveCommandRegister.AddCmd( pCommandFB := ADR(THIS^ ));     
           // set timeout
           SetTimeout(PT := _timeoutCmd, rTimer := _timerCmd);
           // inc step counter
          _stepCmd := _stepCmd + 1;
         END_IF 
       END_IF


  01:  // Wait for responce received
       IF ( _responseReceived )
       THEN
         // reset response received flag
        _responseReceived := FALSE;
         // update state flags
         OnUpdateStateFlags(_response.State);
         // update state flags
         OnApplyOutCmd(_response.State);

         // Done, Aborted or Error ?
         IF (_response.State >= CmdMessageState.DONE )
         THEN
           // set timeout
           SetTimeout(PT := _timeoutCmd, rTimer := _timerCmd);
           // inc step counter
          _stepCmd := _stepCmd + 1; 
         END_IF
       END_IF


  02: IF (NOT Enable)
      THEN
        Reset();
      END_IF  

ELSE
  // invalid step
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_STEP, Overwrite := TRUE );
END_CASE



// Reset FB
IF (( _enable_R.Q ) OR
    ( _enable_F.Q ))
THEN
  Reset();
END_IF

