                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.FrameNo = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.FrameNo));                            
  RETURN;
END_IF


// Check ParCmd.TargetFrameNo valid ? 
IF (( ParCmd.TargetFrameNo <   0 ) OR   
    ( ParCmd.TargetFrameNo > 254 ))
THEN
