                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.TargetFrameNo = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.TargetFrameNo));                            
  RETURN;
END_IF

