  ParameterCnt : DINT;
END_VAR

METHOD FB_init : BOOL
VAR_INPUT
  /// if TRUE, the retain variables are initialized (warm start / cold start)
  bInitRetains : BOOL; 
  /// if TRUE, the instance afterwards gets moved into the copy code (online change)
  bInCopyCode  : BOOL;  
END_VAR

ST.xhtml:
MyType := 'MC_ForceControlFB';

ExecMode := ExecutionMode.CONTINUOUS;
Priority := PriorityLevel.NORMAL;

InterfaceAsPlainText.xhtml:
METHOD FB_init : BOOL
VAR_INPUT
  /// if TRUE, the retain variables are initialized (warm start / cold start)
  bInitRetains : BOOL; 
  /// if TRUE, the instance afterwards gets moved into the copy code (online change)
  bInCopyCode  : BOOL;  
END_VAR

METHOD PROTECTED OnApplyOutCmd
VAR_INPUT
  /// Command message state
  State : CmdMessageState;
END_VAR

ST.xhtml:
IF ( State = CmdMessageState.EMPTY ) 
THEN
  // Reset command outputs
  SysDepMemSet(pDest := ADR(OutCmd), Value := 0, DataLen := SIZEOF(OutCmd));         
END_IF

IF (( State = CmdMessageState.ACTIVE ) OR
    ( State = CmdMessageState.DONE   ))
THEN
  // Update results
  OutCmd.ForceStatus.ForceControlEnabled         := _response.ForceStatus.0;
  OutCmd.ForceStatus.ForceLimitEnabled           := _response.ForceStatus.1;
  OutCmd.ForceStatus.ApplyingForce               := _response.ForceStatus.2;
  OutCmd.ForceStatus.MaxDeviationReached         := _response.ForceStatus.3;
  OutCmd.ForceStatus.SpecifiedForceTorqueReached := _response.ForceStatus.4;
  OutCmd.ForceStatus.SpecifiedForceLimitReached  := _response.ForceStatus.5;
  OutCmd.ForceStatus.Bit06                       := _response.ForceStatus.6;
  OutCmd.ForceStatus.Bit07                       := _response.ForceStatus.7;  
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED OnApplyOutCmd
VAR_INPUT
  /// Command message state
  State : CmdMessageState;
END_VAR

METHOD Protected OnExecCancel : DINT
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal return value 
 _retVal    : DINT;
END_VAR

METHOD Protected OnExecCancel : DINT
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal return value 
 _retVal    : DINT;
END_VAR

ST.xhtml:
OnExecCancel := RobotLibraryConstants.RUNNING;

CASE _stepCancel OF

  0: // set busy flag
     Busy := TRUE;

     // Create log entry
     CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                             MessageType := MessageType.CMD,
                             Severity    := Severity.DEBUG,
                             MessageCode := 0,
                             MessageText := 'Execution of {1} cancelled',
                             Para1       := MyType);                 

     // try to remove cmd
    _retVal := AxesGroup.Acyclic.ActiveCommandRegister.RemoveCmd(_uniqueID);

     // check result of removement       
     IF ( _retVal = RobotLibraryConstants.OK )
     THEN
       // Reset step counter
      _stepCancel := 0;
       // finished okay
       OnExecCancel := RobotLibraryConstants.OK;

       // Create log entry
       CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                               MessageType := MessageType.CMD,
                               Severity    := Severity.DEBUG,
                               MessageCode := 0,
                               MessageText := '{1} successfully removed from ACR',
                               Para1       := MyType);                 
     ELSE
       // set timeout
       SetTimeout(PT := _timeoutCancel, rTimer := _timerCancel);
       // inc step counter
      _stepCancel := _stepCancel + 1; 

       // Create log entry
       CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                               MessageType := MessageType.CMD,
                               Severity    := Severity.DEBUG,
                               MessageCode := 0,
                               MessageText := '{1} was not removed from ACR because execution was already in progress',
                               Para1       := MyType);                 
     END_IF       


 1:  // call clear error 
     OnExecCancel := OnExecErrorClear(AxesGroup := AxesGroup);  

     IF ( OnExecCancel = RobotLibraryConstants.OK)
     THEN
       // Reset busy flag
       Busy := FALSE;
       // Reset step counter
      _stepCancel := 0;
       // finished okay
       OnExecCancel := RobotLibraryConstants.OK;
     END_IF  

ELSE
  // invalid step
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_STEP, Overwrite := TRUE );
END_CASE  



// reset step counter
IF (OnExecCancel <> RobotLibraryConstants.RUNNING)
THEN
  // Reset FB variables
  Reset();
  // Reset step counter
 _stepCancel := 0;
END_IF

InterfaceAsPlainText.xhtml:
METHOD Protected OnExecCancel : DINT
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal return value 
 _retVal    : DINT;
END_VAR

METHOD PROTECTED OnExecErrorClear : DINT
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

ST.xhtml:
OnExecErrorClear := RobotLibraryConstants.RUNNING;

CASE _stepClearError OF

  0:  // set busy flag
      Busy := TRUE;
      // trigger parameter update to disable FB
     _parameterUpdateInternal := TRUE;
      // call Check Parameter changed method to trigger the parameter update to disable the function
      CheckParameterChanged(AxesGroup := AxesGroup);
      // set timeout
      SetTimeout(PT := _timeoutClearError, rTimer := _timerClearError);
      // inc step counter
     _stepClearError := _stepClearError + 1; 

  1: IF ( _responseReceived )
     THEN
       // reset response received flag
      _responseReceived := FALSE;
       // reset step counter
      _stepClearError := 0;
       // finished
       OnExecErrorClear := RobotLibraryConstants.OK;
     ELSE
       // timeout exceeded ? 
       IF (CheckTimeout(_timerClearError) = RobotLibraryConstants.OK)
       THEN
         OnExecErrorClear := RobotLibraryConstants.HAS_ERROR;
       END_IF
	   END_IF
ELSE
  // invalid step
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_STEP, Overwrite := TRUE );
END_CASE


// reset step counter
IF (OnExecErrorClear <> RobotLibraryConstants.RUNNING)
THEN
  // Reset 
  Reset();     
  // reset step counter
 _stepClearError := 0;
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED OnExecErrorClear : DINT
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

METHOD PROTECTED OnExecRun : DINT
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

ST.xhtml:
// call base implementation
SUPER^.OnExecRun(AxesGroup := AxesGroup);

CASE _stepCmd OF

  00:  IF ( _enable_R.Q ) AND ( NOT Error) 
       THEN
         // reset the rising edge
        _enable_R();       
         // reset the falling edge
        _enable_F();     

         // Check function is supported and parameter are valid ?
         IF (( CheckFunctionSupported( AxesGroup := AxesGroup )) AND
             ( CheckParameterValid   ( AxesGroup := AxesGroup )))      
         THEN
           // set busy flag
           Busy := TRUE;
           // Reset command outputs
           SysDepMemSet(pDest := ADR(OutCmd), Value := 0, DataLen := SIZEOF(OutCmd));         
           // apply command parameter
          _parCmd := ParCmd;
           // init parameter sequence
          _command.ParSeq := 1;
           // create command data
           CommandData := CreateCommandPayload(AxesGroup := AxesGroup);
           // Add command to active command register
          _uniqueID := AxesGroup.Acyclic.ActiveCommandRegister.AddCmd( pCommandFB := ADR(THIS^ ));     
           // set timeout
           SetTimeout(PT := _timeoutCmd, rTimer := _timerCmd);
           // inc step counter
          _stepCmd := _stepCmd + 1; 
         END_IF   
       END_IF


  01:  // Wait for responce received
       IF ( _responseReceived )
       THEN
         // reset response received flag
        _responseReceived := FALSE;
         // update state flags
         OnUpdateStateFlags(_response.State);
         // update state flags
         OnApplyOutCmd(_response.State);

         // Done, Aborted or Error ?
         IF (_response.State >= CmdMessageState.DONE )
         THEN
           // set timeout
           SetTimeout(PT := _timeoutCmd, rTimer := _timerCmd);
           // inc step counter
          _stepCmd := _stepCmd + 1;
         END_IF 
       END_IF

       // do not abort directly, so that the ParSeq update can be send
       IF ( _enable_F.Q ) 
       THEN
         // Set Busy flag
         Busy := TRUE;
         // trigger parameter update to disable FB
        _parameterUpdateInternal := TRUE;
         // reset the falling edge
        _enable_F();
         // set timeout
         SetTimeout(PT := _timeoutCmd, rTimer := _timerCmd);
         // inc step counter
        _stepCmd := _stepCmd + 1; 
       END_IF

      // Wait for response received or timeout or not Initialized
  02: IF ((    _responseReceived                                   )  OR 
          (     CheckTimeout(_timerCmd) = RobotLibraryConstants.OK )) OR 
         (( NOT AxesGroup.State.Initialized                        )  AND
          ( NOT AxesGroup.State.Synchronized                       ))
      THEN
        Reset();   
	    END_IF

ELSE
  // invalid step
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_STEP, Overwrite := TRUE );
END_CASE



// Reset FB
IF (( _enable_R.Q ) OR
    ( _enable_F.Q ))
THEN
  Reset();  
END_IF

InterfaceAsPlainText.xhtml:
METHOD PROTECTED OnExecRun : DINT
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

METHOD PROTECTED OnUpdateStateFlags
VAR_INPUT
  /// Command message state
  State : CmdMessageState;
END_VAR

ST.xhtml:
// Reset State flags
Valid := FALSE; 

// Update enable flag
Enabled := _response.ForceStatus.0;

CASE State OF

  // No operation or process is active
  CmdMessageState.EMPTY               :;
  // Created but not yet started
  CmdMessageState.CREATED             :;
  // Buffered and awaiting execution
  CmdMessageState.BUFFERED            : CommandBuffered    := TRUE;
                                        ParameterAccepted  := TRUE;  
  // Buffered in planner for future execution
  CmdMessageState.BUFFERED_IN_PLANNER : CommandBuffered    := TRUE;
                                        ParameterAccepted  := TRUE; 
  // Currently active and in progress
  CmdMessageState.ACTIVE              : Valid              := TRUE; 
  // Interrupted and awaiting continuation
  CmdMessageState.INTERRUPTED         :;  
  // Requested for abort
  CmdMessageState.ABORT_REQUEST       :;
  // Successfully completed
  CmdMessageState.DONE                : Busy               := FALSE;
  // Aborted before completion
  CmdMessageState.ABORTED             : Busy               := FALSE;
  // Encountered an error during execution
  CmdMessageState.ERROR               : Error              := TRUE;
                                        Busy               := FALSE;
                                        // ST-FIX F106: error response without payload
                                        Enabled            := FALSE;
END_CASE

InterfaceAsPlainText.xhtml:
METHOD PROTECTED OnUpdateStateFlags
VAR_INPUT
  /// Command message state
  State : CmdMessageState;
END_VAR

METHOD INTERNAL ParseResponsePayload : DINT
VAR_INPUT
  /// Response data
  ResponseData : RobotLibraryResponseDataFB;
  /// Timestamp
  Timestamp    : SystemTime;  
END_VAR
VAR
  /// Parameter count
 _parameterCnt : DINT;
END_VAR
// Table 6-720: Received CMD payload (RC to PLC) of "ForceControl"
// --------------------------
// Header
// --------------------------
// Byte 00 : USINT      - ParSeq | State     
// Byte 01 : SINT       - AlarmMessageSeverity    
// Byte 02 : UINT       - AlarmMessageCode HB
// Byte 03 :            - AlarmMessageCode LB
// --------------------------
// Datablock
// --------------------------
// Byte 04 : USINT      - ForceStatus 
// --------------------------

METHOD INTERNAL ParseResponsePayload : DINT
VAR_INPUT
  /// Response data
  ResponseData : RobotLibraryResponseDataFB;
  /// Timestamp
  Timestamp    : SystemTime;  
END_VAR
VAR
  /// Parameter count
 _parameterCnt : DINT;
END_VAR
// Table 6-720: Received CMD payload (RC to PLC) of "ForceControl"
// --------------------------
// Header
// --------------------------
// Byte 00 : USINT      - ParSeq | State     
// Byte 01 : SINT       - AlarmMessageSeverity    
// Byte 02 : UINT       - AlarmMessageCode HB
// Byte 03 :            - AlarmMessageCode LB
// --------------------------
// Datablock
// --------------------------
// Byte 04 : USINT      - ForceStatus 
// --------------------------

ST.xhtml:
// call base implementation to parse the header from payload buffer
ResponseData.PayloadPtr := SUPER^.ParseResponsePayload(ResponseData := ResponseData, Timestamp := Timestamp);

// ST-FIX F100: missing (trailing zero) bytes of the payload are 0, no values of the previous response
SysDepMemSet( pDest := ADR(_response), Value := 0, DataLen := SIZEOF(_response));

// copy parsed header to response
_response.ParSeq                := _rspHeader.ParSeq;
_response.State                 := _rspHeader.State;
_response.AlarmMessageSeverity  := _rspHeader.AlarmMessageSeverity;
_response.AlarmMessageCode      := _rspHeader.AlarmMessageCode;

// Check payload remaining ? 
IF ( ResponseData.IsPayloadRemaining)
THEN 
  // Get Response.ForceStatus
 _response.ForceStatus := ResponseData.GetByte();
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;
END_IF


// Create logging
ParseResponsePayloadLog(ResponseData := ResponseData, Timestamp := Timestamp, ParameterCnt := _parameterCnt);

