VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// Parameter count
 _parameterCnt : DINT;
END_VAR
// Table 6-25: Sent CMD payload (PLC to RC) of "EnableRobot"
// --------------------------
// Header
// --------------------------
// Byte 00 : UINT  - Type HB     
// Byte 01 :       - Type LB    
// Byte 02 : USINT - Reserve | ExecutionMode
// Byte 03 : USINT - ParSeq  | Priority
// --------------------------
// Datablock
// --------------------------
// Byte 04 : BOOL  - Enable
// Byte 05 : BOOL  - HoldToRun
// Byte 06 : USINT - StepMode   
// Byte 07 : BOOL  - ManualStep
// --------------------------

METHOD INTERNAL CreateCommandPayload : RobotLibraryCommandDataFB
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// Parameter count
 _parameterCnt : DINT;
END_VAR
// Table 6-25: Sent CMD payload (PLC to RC) of "EnableRobot"
// --------------------------
// Header
// --------------------------
// Byte 00 : UINT  - Type HB     
// Byte 01 :       - Type LB    
// Byte 02 : USINT - Reserve | ExecutionMode
// Byte 03 : USINT - ParSeq  | Priority
// --------------------------
// Datablock
// --------------------------
// Byte 04 : BOOL  - Enable
// Byte 05 : BOOL  - HoldToRun
// Byte 06 : USINT - StepMode   
// Byte 07 : BOOL  - ManualStep
// --------------------------

ST.xhtml:
                  // set command parameter 
_command.CmdTyp    :=  CmdType.EnableRobot;
_command.ExecMode  :=  ExecMode;
_command.ParSeq    := _command.ParSeq;
_command.Priority  :=  Priority;
_command.Enable    :=  Enable;
_command.HoldToRun := _parCmd.HoldToRun;
_command.StepMode  := _parCmd.StepMode;
_command.ManualStep:= _parCmd.ManualStep;


// copy command data to header
_cmdHeader := _command;
// call base implementation to copy header to payload buffer
CreateCommandPayload := SUPER^.CreateCommandPayload(AxesGroup := AxesGroup);


// Check parameter must be added ? 
IF ( CheckAddParameter(CreateCommandPayload.PayloadPtr))
THEN
  // add command.Enable
  CreateCommandPayload.AddBool(_command.Enable);
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;  
END_IF


// Check parameter must be added ? 
IF ( CheckAddParameter(CreateCommandPayload.PayloadPtr))
THEN
  // add command.StepMode
  CreateCommandPayload.AddUsint(_command.StepMode);
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;  
END_IF


// Check parameter must be added ? 
IF ( CheckAddParameter(CreateCommandPayload.PayloadPtr))
THEN
  // add command.HoldToRun
  CreateCommandPayload.AddByte(BOOL_TO_BYTE(_command.HoldToRun) OR SHL(BOOL_TO_BYTE(_command.ManualStep), 1)); // ST-FIX F37
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;  
END_IF


// Check parameter must be added ? 
IF ( CheckAddParameter(CreateCommandPayload.PayloadPtr))
THEN
  // add command.ManualStep
  CreateCommandPayload.AddByte(0); // ST-FIX F37: reserved byte, the value is bit 1 of the byte before                      
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;  
END_IF


// Create logging
CreateCommandPayloadLog(AxesGroup := AxesGroup, ParameterCnt := _parameterCnt);

