VAR_INPUT
  /// Response data
  ResponseData : RobotLibraryResponseDataFB;
  /// Timestamp
  Timestamp    : SystemTime;  
  /// Parameter count
  ParameterCnt : DINT;
END_VAR

ST.xhtml:
Reset := SUPER^.Reset();

Done               := FALSE;
Busy               := FALSE;
CommandBuffered    := FALSE;

