  _frameInvalid : BOOL;
  /// ST-FIX F79: last error state of the RC during the initialization (reported at the init timeout)
  _initErrorState : TelegramState;
END_VAR

VAR
  _turns : BYTE; // ST-FIX F60: turn number nibble
END_VAR

VAR
  _restartReset : BOOL; // ST-FIX F23: interface reset on the RC requested by a restart
END_VAR


              /// Handles multiple mechanisms required for operation of the interface.
/// For maximal performance, this FB must be called after the function FB's, 
/// so that the data can be written to the fieldbus in the same cycle as the start of FB occours 
FUNCTION_BLOCK MC_RobotTaskFB EXTENDS RobotLibraryLogFB
