IF ( ( _turns AND 16#08 ) <> 0 )
THEN
  AxesGroup.CyclicOptional.RobToPlc.CartesianPosition.TurnNumber.J2Turns := INT_TO_SINT(-SINT_TO_INT(AxesGroup.CyclicOptional.RobToPlc.CartesianPosition.TurnNumber.J2Turns));
