FOR _fragIdx := 0 TO AxesGroup.State.FragmentCountSend[_seqIdx] DO IF ( Telegram.PlcToRob.Sequence[_seqIdx].Fragment[_fragIdx].Header.PayloadLength > 0 ) THEN // Create log entry CreateLogMessagePara6 ( Timestamp := SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := 'SendData: added Fragment [{1}] with PayloadLength = {2}, HeaderLength = {3}, CmdID <{4}>, Cmd <{5}> Fragment-Action Bits:{6}' , Para1 := DINT_TO_STRING(_fragIdx), Para2 := UINT_TO_STRING (Telegram.PlcToRob.Sequence[_seqIdx].Fragment[_fragIdx].Header.PayloadLength), Para3 := DINT_TO_STRING(SIZEOF (Telegram.PlcToRob.Sequence[_seqIdx].Fragment[_fragIdx].Header)), Para4 := UINT_TO_STRING (Telegram.PlcToRob.Sequence[_seqIdx].Fragment[_fragIdx].Header.CmdID), Para5 := CMD_TYPE_TO_STRING (Telegram.PlcToRob.Sequence[_seqIdx].Fragment[_fragIdx].Command.Header.CmdType), Para6 := FRAGMENT_ACTION_TO_STRING (Telegram.PlcToRob.Sequence[_seqIdx].Fragment[_fragIdx].Header.FragmentAction));
// Create log entry CreateLogMessagePara2 ( Timestamp := SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := 'SendData: added Fragment [{1}] will be executed with ExecMode = [{2}]' , Para1 := DINT_TO_STRING(_fragIdx), Para2 := EXECUTION_MODE_TO_STRING(Telegram.PlcToRob.Sequence[_seqIdx].Fragment[_fragIdx].Command.Header.ExecMode));
END_IF END_FOR END_IF END_FOR

