THEN
  // Set Message ID as Acknowlege ID  
 _readMessages.ParCmd.MsgID := _readMessages.OutCmd.MsgId;  
ELSE
  // Reset Acknowlege ID  
 _readMessages.ParCmd.MsgID := 0;
END_IF 



