VAR
  /// Internal step counter name
 _stepName        : STRING;    
  /// Internal reference to step counter
 _rStep           : REFERENCE TO DINT;
  /// Internal reference to timer
 _rTimer          : REFERENCE TO TON;
  /// Internal reference to timeout
