UserData.RCOrderID                         := AxesGroup.State.RobotData.RCOrderID; 
UserData.RCSerialNumber                    := AxesGroup.State.RobotData.RCSerialNumber;
UserData.RASerialNumber                    := AxesGroup.State.RobotData.RASerialNumber;
