  /// Robot assignment of function
  AxesGroup   : AxesGroup;
  /// Inputs of PLC for communication from RC
  RobotInData : ARRAY[*] OF BYTE;
END_VAR

METHOD PROTECTED ParseRecvPayload
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup   : AxesGroup;
