VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup    : AxesGroup; 
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

ST.xhtml:
CheckParameterValid := TRUE;

// Check ParCmd.OperationMode valid ? 
IF (( ParCmd.OperationMode <> OperationMode.AUTO_EXT ) AND  
    ( ParCmd.OperationMode <> OperationMode.T1_EXT   ) AND  
    ( ParCmd.OperationMode <> OperationMode.T2_EXT   ))  
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.OperationMode = {1}',
                          Para1       :=  OPERATION_MODE_TO_STRING(ParCmd.OperationMode));
  RETURN;                          
END_IF

