VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

ST.xhtml:
CheckParameterValid := TRUE;

// Check ParCmd.OperationMode valid ? 
IF (( ParCmd.TargetSequence <> SequenceFlag.PRIMARY_SEQUENCE   ) AND  
    ( ParCmd.TargetSequence <> SequenceFlag.SECONDARY_SEQUENCE ))  
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.TargetSequence = {1}',
                          Para1       :=  SEQUENCE_FLAG_TO_STRING(ParCmd.TargetSequence));
  RETURN;                          
END_IF

