METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

ST.xhtml:
CheckParameterValid := TRUE;


// Check ParCmd.Mode valid ? 
IF (( ParCmd.Mode <> LogonMode.PASSWORD_ONLY         ) AND
    ( ParCmd.Mode <> LogonMode.USERNAME_AND_PASSWORD ) AND
    ( ParCmd.Mode <> LogonMode.LEVEL_ID_AND_PASSWORD ))  
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.Mode = {1}',
                          Para1       := LOGON_MODE_TO_STRING(ParCmd.Mode));

  RETURN;                          
END_IF

// Check ParCmd.Password valid ? 
IF ( ParCmd.Password = '' )
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.Password = {1}',
                          Para1       := ParCmd.Password);

  RETURN;                          
END_IF


// Check ParCmd.Username valid ? 
IF (( ParCmd.Mode     = LogonMode.USERNAME_AND_PASSWORD ) AND // ST-FIX F87: only with user name
    ( ParCmd.Username = ''                              ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.Username = {1}',
                          Para1       := ParCmd.Username);

  RETURN;                          
END_IF


// Check ParCmd.Mode valid ? 
IF (( ParCmd.LevelID <   0 ) OR
    ( ParCmd.LevelID > 127 ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.Mode = {1}',
                          Para1       := LOGON_MODE_TO_STRING(ParCmd.Mode));

  RETURN;                          
END_IF

