ST.xhtml:
// Create log entry for Parameter start CreateLogMessage ( Timestamp := AxesGroup.State.SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := 'Update position with the following parameter(s) :');
// Create log entry for _parCmd.ReadCartesianPosition CreateLogMessagePara1 ( Timestamp := AxesGroup.State.SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := '_parCmd.ReadCartesianPosition = {1}', Para1 := BOOL_TO_STRING(_parCmd.ReadCartesianPosition));
// Create log entry for _parCmd.ReadCartesianPositionExt CreateLogMessagePara1 ( Timestamp := AxesGroup.State.SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := '_parCmd.ReadCartesianPositionExt = {1}', Para1 := BOOL_TO_STRING(_parCmd.ReadCartesianPositionExt));
// Create log entry for _parCmd.ToolNo CreateLogMessagePara1 ( Timestamp := AxesGroup.State.SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := '_parCmd.ToolNo = {1}', Para1 := INT_TO_STRING(_parCmd.ToolNo));
// Create log entry for _parCmd.FrameNo CreateLogMessagePara1 ( Timestamp := AxesGroup.State.SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := '_parCmd.FrameNo = {1}', Para1 := INT_TO_STRING(_parCmd.FrameNo));
// Create log entry for _parCmd.ReadJointPosition CreateLogMessagePara1 ( Timestamp := AxesGroup.State.SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := '_parCmd.ReadJointPosition = {1}', Para1 := BOOL_TO_STRING(_parCmd.ReadJointPosition));
// Create log entry for _parCmd.ReadJointPositionExt CreateLogMessagePara1 ( Timestamp := AxesGroup.State.SystemTime, MessageType := MessageType.CMD, Severity := Severity.DEBUG, MessageCode := 0, MessageText := '_parCmd.ReadJointPositionExt = {1}', Para1 := BOOL_TO_STRING(_parCmd.ReadJointPositionExt));

