Reset := SUPER^.Reset();

Done               := FALSE;
Busy               := FALSE;
Valid              := FALSE;
ParameterAccepted  := FALSE;
CommandBuffered    := FALSE;
CommandAborted     := FALSE;
CommandInterrupted := FALSE;

