ST.xhtml:
// call base implementation to parse the header from payload buffer
ResponseData.PayloadPtr := SUPER^.ParseResponsePayload(ResponseData := ResponseData, Timestamp := Timestamp);

// ST-FIX F100: missing (trailing zero) bytes of the payload are 0, no values of the previous response
SysDepMemSet( pDest := ADR(_response), Value := 0, DataLen := SIZEOF(_response));

// copy parsed header to response
_response.ParSeq               := _rspHeader.ParSeq;
_response.State                := _rspHeader.State;
_response.AlarmMessageSeverity := _rspHeader.AlarmMessageSeverity;
_response.AlarmMessageCode     := _rspHeader.AlarmMessageCode;


// Check payload remaining ? 
IF ( ResponseData.IsPayloadRemaining)
THEN  
  // Get Response.InvocationCounter
 _response.InvocationCounter := ResponseData.GetUsint();
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;
END_IF


// Check payload remaining ? 
IF ( ResponseData.IsPayloadRemaining)
THEN  
  // Get Response.Reserve
 _response.Reserve := ResponseData.GetByte();
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;
END_IF


// Check payload remaining ? 
IF ( ResponseData.IsPayloadRemaining)
THEN  
  // Get Response.OriginID
 _response.OriginID := ResponseData.GetInt();
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;
END_IF


// Get Response.Values[x]
FOR _idx := 0 TO 6
DO
  // Check payload remaining ? 
  IF ( ResponseData.IsPayloadRemaining)
  THEN
    // Get value  
   _response.Values[_idx] := ResponseData.GetInt();
    // inc parameter counter
   _parameterCnt := _parameterCnt + 1;
  END_IF
END_FOR


// Create logging
ParseResponsePayloadLog(ResponseData := ResponseData, Timestamp := Timestamp, ParameterCnt := _parameterCnt);

InterfaceAsPlainText.xhtml:
METHOD INTERNAL ParseResponsePayload : DINT
VAR_INPUT
  /// Response data
  ResponseData : RobotLibraryResponseDataFB;
  /// Timestamp
  Timestamp    : SystemTime;  
END_VAR
VAR 
  /// internal index for loops
 _idx          : DINT;
  /// Parameter count
 _parameterCnt : DINT;
END_VAR
// Table 6-497: Received CMD payload (RC to PLC) of "ReadIntegers"
// --------------------------
// Header
// --------------------------
// Byte 00 : USINT   - ParSeq | State     
// Byte 01 : SINT    - AlarmMessageSeverity    
// Byte 02 : UINT    - AlarmMessageCode HB
// Byte 03 :         - AlarmMessageCode LB
// --------------------------
// Datablock
// --------------------------
// Byte 04 : USINT  - InvocationCounter;
// Byte 05 : BYTE   - Reserved;
// Byte 06 : INT    - OriginID LW HB;
// Byte 07 :        - OriginID LW LB;
// Byte 08 : INT    - Values[0] LW HB;
// Byte 09 :        - Values[0] LW LB;
// Byte 10 : INT    - Values[1] LW HB;
// Byte 11 :        - Values[1] LW LB;
// Byte 12 : INT    - Values[2] LW HB;
// Byte 13 :        - Values[2] LW LB;
// Byte 14 : INT    - Values[3] LW HB;
// Byte 15 :        - Values[3] LW LB;
// Byte 16 : INT    - Values[4] LW HB;
// Byte 17 :        - Values[4] LW LB;
// Byte 18 : INT    - Values[5] LW HB;
// Byte 19 :        - Values[5] LW LB;
// Byte 20 : INT    - Values[6] LW HB;
// Byte 21 :        - Values[6] LW LB;
// --------------------------

METHOD INTERNAL ParseResponsePayloadLog
VAR_INPUT
  /// Response data
  ResponseData : RobotLibraryResponseDataFB;
  /// Timestamp
  Timestamp    : SystemTime;  
  /// Parameter count
  ParameterCnt : DINT;
END_VAR
VAR 
  /// internal index for loops
 _idx : DINT;
END_VAR

METHOD INTERNAL ParseResponsePayloadLog
VAR_INPUT
  /// Response data
  ResponseData : RobotLibraryResponseDataFB;
  /// Timestamp
  Timestamp    : SystemTime;  
  /// Parameter count
  ParameterCnt : DINT;
END_VAR
VAR 
  /// internal index for loops
 _idx : DINT;
END_VAR

ST.xhtml:
// Create log entry for Parameter start
CreateLogMessagePara1 ( Timestamp   := Timestamp,
                        MessageType := MessageType.CMD,
                        Severity    := Severity.DEBUG,
                        MessageCode := 0,
                        MessageText := '{1} parameter(s) to parse from the response data:',
                        Para1       := DINT_TO_STRING(ParameterCnt));


// Return if no parameter is remaining...
IF ( ParameterCnt = 0 ) THEN RETURN; END_IF
// dec remaining parameter(s)                        
ParameterCnt := ParameterCnt - 1;
// Create log entry for InvocationCounter
CreateLogMessagePara1 ( Timestamp   := Timestamp,
                        MessageType := MessageType.CMD,
                        Severity    := Severity.DEBUG,
                        MessageCode := 0,
                        MessageText := 'Response.InvocationCounter = {1}',
                        Para1       :=  USINT_TO_STRING(_response.InvocationCounter));


// Return if no parameter is remaining...
IF ( ParameterCnt = 0 ) THEN RETURN; END_IF
// dec remaining parameter(s)                        
ParameterCnt := ParameterCnt - 1;
// Create log entry for Reserve
CreateLogMessagePara1 ( Timestamp   := Timestamp,
                        MessageType := MessageType.CMD,
                        Severity    := Severity.DEBUG,
                        MessageCode := 0,
                        MessageText := 'Response.Reserve = {1}',
                        Para1       :=  BYTE_TO_STRING(_response.Reserve));


// Return if no parameter is remaining...
IF ( ParameterCnt = 0 ) THEN RETURN; END_IF
// dec remaining parameter(s)                        
ParameterCnt := ParameterCnt - 1;
// Create log entry for OriginID
CreateLogMessagePara1 ( Timestamp   := Timestamp,
                        MessageType := MessageType.CMD,
                        Severity    := Severity.DEBUG,
                        MessageCode := 0,
                        MessageText := 'Response.OriginID = {1}',
                        Para1       :=  INT_TO_STRING(_response.OriginID));

// Create log entry for Values[{x}]
FOR _idx := 0 TO 6
DO
  // Return if no parameter is remaining...
  IF ( ParameterCnt = 0 ) THEN RETURN; END_IF
  // dec remaining parameter(s)                        
  ParameterCnt := ParameterCnt - 1;
  // Create log entry Response.Values
  CreateLogMessagePara2 ( Timestamp   := Timestamp,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.DEBUG,
                          MessageCode := 0,
                          MessageText := 'Response.Values[{2}] = {1}',
                          Para1       :=  INT_TO_STRING(_response.Values[_idx]),
                          Para2       :=  DINT_TO_STRING(_idx));
END_FOR

