VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup    : AxesGroup; 
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

ST.xhtml:
CheckParameterValid := TRUE;

// Check ParCmd.LoadNo valid ? 
IF (( ParCmd.LoadNo <  -1                                                ) OR  
    ( ParCmd.LoadNo =   0                                                ) OR 
    ( ParCmd.LoadNo > 254                                                ) OR
    ( ParCmd.LoadNo > AxesGroup.State.ConfigurationData.HighestLoadIndex ) OR
    ( ParCmd.LoadNo > AxesGroup.State.UnifiedLoadIndex                   ))         
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;

  // Check LoadNo available on RC ? 
  IF (( ParCmd.LoadNo > AxesGroup.State.ConfigurationData.HighestLoadIndex ) AND ( ParCmd.LoadNo <= 254 )) // ST-FIX F98: outside -1..254 is a range error
  THEN
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_LOADNO_UNAVAILABLE, Overwrite := TRUE );
  ELSE
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_LOADNO_RANGE, Overwrite := TRUE );
	END_IF  

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.LoadNo = {1}',
                          Para1       :=  INT_TO_STRING(ParCmd.LoadNo));
  RETURN;                          
END_IF

