// Byte 17 :             JerkReference HW LB;
// Byte 18 : USINT       DataChanged;
// --------------------------

ST.xhtml:
// call base implementation to parse the header from payload buffer
ResponseData.PayloadPtr := SUPER^.ParseResponsePayload(ResponseData := ResponseData, Timestamp := Timestamp);

// ST-FIX F100: missing (trailing zero) bytes of the payload are 0, no values of the previous response
SysDepMemSet( pDest := ADR(_response), Value := 0, DataLen := SIZEOF(_response));

// copy parsed header to response
_response.ParSeq               := _rspHeader.ParSeq;
_response.State                := _rspHeader.State;
_response.AlarmMessageSeverity := _rspHeader.AlarmMessageSeverity;
_response.AlarmMessageCode     := _rspHeader.AlarmMessageCode;


// Check payload remaining ? 
IF ( ResponseData.IsPayloadRemaining)
THEN  
  // Get Response.DynamicValues.Timestamp.IEC_DATE
 _response.Timestamp.IEC_DATE := ResponseData.GetIecDate();
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;
END_IF


// Check payload remaining ? 
IF ( ResponseData.IsPayloadRemaining)
THEN  
  // Get Response.DynamicValues.Timestamp.IEC_TIME
 _response.Timestamp.IEC_TIME := ResponseData.GetIecTime();
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;
END_IF


// Check payload remaining ? 
IF ( ResponseData.IsPayloadRemaining)
THEN  
  // Get Response.DynamicValues.VelocityRate
 _response.VelocityReference := ResponseData.GetReal();
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;
END_IF


// Check payload remaining ? 
IF ( ResponseData.IsPayloadRemaining)
THEN  
  // Get Response.DynamicValues.AccelerationRate
 _response.AccelerationReference := ResponseData.GetReal();

  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;
END_IF


// Check payload remaining ? 
IF ( ResponseData.IsPayloadRemaining)
THEN  
  // Get Response.DynamicValues.DecelerationRate
 _response.DecelerationReference := ResponseData.GetReal();
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;
END_IF


// Check payload remaining ? 
IF ( ResponseData.IsPayloadRemaining)
THEN  
  // Get Response.DynamicValues.JerkRate
 _response.JerkReference := ResponseData.GetReal();
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;
END_IF


// Check payload remaining ? 
IF ( ResponseData.IsPayloadRemaining)
THEN  
  // Get Response.DataChanged
 _response.DataChanged := ResponseData.GetBool();
  // inc parameter counter
 _parameterCnt := _parameterCnt + 1;
END_IF


// Create logging
ParseResponsePayloadLog(ResponseData := ResponseData, Timestamp := Timestamp, ParameterCnt := _parameterCnt);

