ParameterCnt := ParameterCnt - 1;
// Create log entry for no parameter 
CreateLogMessage      ( Timestamp   := Timestamp,
                        MessageType := MessageType.CMD,
                        Severity    := Severity.DEBUG,
                        MessageCode := 0,
                        MessageText := 'This command has no parameter to parse...');

