    ( ParCmd.Offset.Config.Shoulder <> ArmConfigShoulder.BACK       ) AND
    ( ParCmd.Offset.Config.Shoulder <> ArmConfigShoulder.FRONT      ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
