// Byte 17 :       Data[2];
// Byte 18 :       Data[2];
// Byte 19 :       Data[2];
// Byte 20 : REAL  Data[3];
// Byte 21 :       Data[3];
// Byte 22 :       Data[3];
// Byte 23 :       Data[3];
// Byte 24 : REAL  Data[4];
// Byte 25 :       Data[4];
// Byte 26 :       Data[4];
// Byte 27 :       Data[4];
