METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

ST.xhtml:
                  CheckParameterValid := TRUE;

// Check ParCmd.ProcessingMode defined ? 
IF (( ProcessingMode < ProcessingModeEnum.BUFFERED         ) OR // ST-FIX F26
    ( ProcessingMode > ProcessingModeEnum.TRIGGER_MULTIPLE ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_DEFINED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;                          
END_IF

// Check ProcessingMode valid ? 
IF (( ProcessingMode <> ProcessingModeEnum.DEACTIVATE       ) AND 
    ( ProcessingMode <> ProcessingModeEnum.TRIGGER_ONCE     ) AND  
    ( ProcessingMode <> ProcessingModeEnum.TRIGGER_MULTIPLE ))  
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;                          
END_IF


// Check ParCmd.TriggerMode valid ? 
IF (( ParCmd.TriggerMode < TriggerModeIo.DIGITAL_INPUT_RISING_EDGE                                ) OR
    ( ParCmd.TriggerMode > TriggerModeIo.REAL_REGISTER_ENTERING_OR_LEAVING_DEFINED_RANGE_INVERTED ))
THEN                                                        
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.TriggerMode = {1}',
                          Para1       := TRIGGER_MODE_IO_TO_STRING(ParCmd.TriggerMode));
  RETURN;                          
END_IF


// Check ParCmd.Index valid ? 
IF  (( ParCmd.Index <   0 ) OR
     ( ParCmd.Index > 255 ))     
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.Index = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.Index));
  RETURN;
END_IF


// Check ParCmd.BitIndex valid ? 
IF  (( ParCmd.BitIndex <   0 ) OR
     ( ParCmd.BitIndex > 255 ))     
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.BitIndex = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.BitIndex));
  RETURN;
END_IF


FOR _idx := 1 TO 2
DO
  // Check ParCmd.IntValue[x] valid ? 
  IF (( ParCmd.IntValue[_idx] < -32768 ) OR
      ( ParCmd.IntValue[_idx] >  32767 ))
  THEN
    // Parameter not valid
    CheckParameterValid := FALSE;
    // Set error
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

    // Create log entry
    CreateLogMessagePara2 ( Timestamp   := AxesGroup.State.SystemTime,
                            MessageType := MessageType.CMD,
                            Severity    := Severity.ERROR,
                            MessageCode := ErrorID,
                            MessageText := 'Invalid Parameter ParCmd.IntValue[{2}] = {1}',
                            Para1       := INT_TO_STRING(ParCmd.IntValue[_idx]),
                            Para2       := DINT_TO_STRING(_idx));
    EXIT;                            
    RETURN;                          
  END_IF


  // Check ParCmd.RealValue[x] valid ? 
  IF ( SysDepIsValidReal(ParCmd.RealValue[_idx]) = FALSE ) 
  THEN
    // Parameter not valid
    CheckParameterValid := FALSE;
    // Set error
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

    // Create log entry
    CreateLogMessagePara2 ( Timestamp   := AxesGroup.State.SystemTime,
                            MessageType := MessageType.CMD,
                            Severity    := Severity.ERROR,
                            MessageCode := ErrorID,
                            MessageText := 'Invalid Parameter ParCmd.RealValue[{2}] = {1}',
                            Para1       := VALID_REAL_TO_STRING(ParCmd.RealValue[_idx]),
                            Para2       := DINT_TO_STRING(_idx));
    EXIT;                            
    RETURN;                          
  END_IF
END_FOR


// Check ParCmd.ListenerID valid ? 
IF  (( ParCmd.ListenerID <   0 ) OR
     ( ParCmd.ListenerID > 127 ))     
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_LISTENERID_MUST_BE_POSITIVE (* ST-FIX F69 *), Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ListenerID = {1}',
                          Para1       := SINT_TO_STRING(ParCmd.ListenerID));
  RETURN;
END_IF


// Check ParCmd.EmitterID valid ? 
IF  (( ParCmd.EmitterID < -127 ) OR
     ( ParCmd.EmitterID >  127 ))     
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_EMITTERID_NOT_ALLOWED (* ST-FIX F69 *), Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.EmitterID = {1}',
                          Para1       := SINT_TO_STRING(ParCmd.EmitterID));
  RETURN;
END_IF

// ST-FIX F69: trigger IDs and SequenceFlag (table 7-1, 5.5.12.4, e.g. table 6-496)
IF ( CheckParameterValid ) AND ( ProcessingMode <> ProcessingModeEnum.DEACTIVATE ) AND NOT ( ProcessingMode >= ProcessingModeEnum.TRIGGER_BUFFERED ) AND ( ParCmd.ListenerID > 0 )
THEN
  CheckParameterValid := FALSE;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_LISTENERID_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ListenerID <> 0 with ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;
END_IF

