METHOD PROTECTED CheckParameterChanged : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup    : AxesGroup; 
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

ST.xhtml:
CheckParameterValid := TRUE;


// Check ParCmd.WorkAreaNo valid ? 
IF (( ParCmd.WorkAreaNo < 0                                                      ) OR
    ( ParCmd.WorkAreaNo > 254                                                    ) OR
    ( ParCmd.WorkAreaNo > AxesGroup.State.ConfigurationData.HighestWorkAreaIndex ) OR
    ( ParCmd.WorkAreaNo > AxesGroup.State.UnifiedWorkAreaIndex                   ))         
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;

  // Check LoadNo available on RC ? 
  IF ( ParCmd.WorkAreaNo > AxesGroup.State.ConfigurationData.HighestWorkAreaIndex )
  THEN
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_WORKAREANO_UNAVAILABLE, Overwrite := TRUE );
  ELSE
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_WORKAREANO_RANGE, Overwrite := TRUE );
	END_IF  

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.WorkAreaNo = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.WorkAreaNo));
  RETURN;
END_IF


// Check ParCmd.ActivateArea valid ? 
IF (( ParCmd.ActivateArea <> FALSE ) AND
    ( ParCmd.ActivateArea <> TRUE  ))

THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ActivateArea = {1}',
                          Para1       := BOOL_TO_STRING(ParCmd.ActivateArea));
  RETURN;
END_IF

