ST.xhtml:
MyType := 'MC_ReadWorkAreaFB';

ExecMode := ExecutionMode.PARALLEL;
Priority := PriorityLevel.NORMAL;

InterfaceAsPlainText.xhtml:
METHOD FB_init : BOOL
VAR_INPUT
