METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR

ST.xhtml:
                  CheckParameterValid := TRUE;

// Check ParCmd.ProcessingMode defined ? 
IF (( ProcessingMode < ProcessingModeEnum.BUFFERED         ) OR // ST-FIX F26
    ( ProcessingMode > ProcessingModeEnum.TRIGGER_MULTIPLE ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_DEFINED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;                          
END_IF

// Check ProcessingModea valid ? 
IF (( ProcessingMode <> ProcessingModeEnum.BUFFERED ) AND
    ( ProcessingMode <> ProcessingModeEnum.ABORTING ) AND
    ( ProcessingMode <> ProcessingModeEnum.PARALLEL ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;
END_IF


// Check SequenceFlag valid ? 
IF (( SequenceFlag <> SequenceFlagEnum.NO_SEQUENCE        ) AND
    ( SequenceFlag <> SequenceFlagEnum.PRIMARY_SEQUENCE   ) AND
    ( SequenceFlag <> SequenceFlagEnum.SECONDARY_SEQUENCE ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_SEQFLAG_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter SequenceFlag = {1}',
                          Para1       := SEQUENCE_FLAG_TO_STRING(SequenceFlag));
  RETURN;
END_IF


// Check ParCmd.FrameNo valid ? 
IF (( ParCmd.FrameNo < 0                                                   ) OR  
    ( ParCmd.FrameNo > 254                                                 ) OR
    ( ParCmd.FrameNo > AxesGroup.State.ConfigurationData.HighestFrameIndex ) OR
    ( ParCmd.FrameNo > AxesGroup.State.UnifiedFrameIndex                   ))         
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;

  // Check FrameNo available on RC ? 
  IF (( ParCmd.FrameNo > AxesGroup.State.ConfigurationData.HighestFrameIndex ) AND ( ParCmd.FrameNo <= 254 )) // ST-FIX F98: outside -1..254 is a range error
  THEN
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_FRAMENO_UNAVAILABLE, Overwrite := TRUE );
  ELSE
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_FRAMENO_RANGE, Overwrite := TRUE );
	END_IF  

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.FrameNo = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.FrameNo));
  RETURN;
END_IF


// Check ParCmd.FrameData.ReferenceFrame valid ? 
IF (( ParCmd.FrameData.ReferenceFrame < 0   ) OR
    ( ParCmd.FrameData.ReferenceFrame > 254 ))      
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.FrameData.ReferenceFrame = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.FrameData.ReferenceFrame));
  RETURN;
END_IF


// Check ParCmd.FrameData.X ? 
IF ( SysDepIsValidReal(ParCmd.FrameData.X) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.FrameData.X = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.FrameData.X));
  RETURN;                          
END_IF


// Check ParCmd.FrameData.Y ? 
IF ( SysDepIsValidReal(ParCmd.FrameData.Y) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.FrameData.Y = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.FrameData.Y));
  RETURN;                          
END_IF


// Check ParCmd.FrameData.Z ? 
IF ( SysDepIsValidReal(ParCmd.FrameData.Z) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.FrameData.Z = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.FrameData.Z));
  RETURN;                          
END_IF


// Check ParCmd.FrameData.Rx ? 
IF ( SysDepIsValidReal(ParCmd.FrameData.Rx) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.FrameData.Rx = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.FrameData.Rx));
  RETURN;                          
END_IF

// Check ParCmd.FrameData.Ry ? 
IF ( SysDepIsValidReal(ParCmd.FrameData.Ry) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.FrameData.Ry = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.FrameData.Ry));
  RETURN;                          
END_IF


// Check ParCmd.FrameData.Rz ? 
IF ( SysDepIsValidReal(ParCmd.FrameData.Rz) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.FrameData.Rz = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.FrameData.Rz));
  RETURN;                          
END_IF

// ST-FIX F69: trigger IDs and SequenceFlag (table 7-1, 5.5.12.4, e.g. table 6-496)
// ST-FIX F83: not for DEACTIVATE (it is sent with the SequenceFlag of the command it ends)
IF ( CheckParameterValid ) AND ( ProcessingMode <> ProcessingModeEnum.DEACTIVATE ) AND ( ( (( ProcessingMode = ProcessingModeEnum.BUFFERED ) OR ( ProcessingMode = ProcessingModeEnum.ABORTING ) OR ( ProcessingMode = ProcessingModeEnum.TRIGGER_BUFFERED ) OR ( ProcessingMode = ProcessingModeEnum.TRIGGER_ABORTING )) ) = ( SequenceFlag = SequenceFlagEnum.NO_SEQUENCE ) )
THEN
  CheckParameterValid := FALSE;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_SEQFLAG_INVALID_IN_PROC_MODE, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara2 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter SequenceFlag = {1} with ProcessingMode = {2}',
                          Para1       := SEQUENCE_FLAG_TO_STRING(SequenceFlag),
                          Para2       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;
END_IF

