MyType := 'MC_WriteIntegersFB';

ExecMode       := ExecutionMode.PARALLEL;
Priority       := PriorityLevel.NORMAL;
ProcessingMode := ProcessingModeEnum.PARALLEL;
SequenceFlag   := SequenceFlagEnum.NO_SEQUENCE;

