IF (( SysDepIsValidReal(ParCmd.DynamicValues.VelocityRate) = FALSE ) OR
    ( ParCmd.DynamicValues.VelocityRate > 655.35 )) // ST-FIX F97: UINT with factor 100 in the telegram 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_VELOCITY_INVALID, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.DynamicValues.VelocityRate = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.DynamicValues.VelocityRate));

  RETURN;                          
