METHOD PROTECTED OnApplyOutCmd
VAR_INPUT
  /// Command message state
  State : CmdMessageState;
END_VAR

ST.xhtml:
IF ( State = CmdMessageState.EMPTY ) 
THEN
  // Reset command outputs
  SysDepMemSet(pDest := ADR(OutCmd), Value := 0, DataLen := SIZEOF(OutCmd));         
END_IF

IF (( State = CmdMessageState.ACTIVE ) OR
    ( State = CmdMessageState.DONE   ))
THEN
  // Update results
  OutCmd.DefaultDynamicValues.VelocityRate     := PERCENT_UINT_TO_REAL(_response.VelocityRate     , IsOptional := FALSE); 
  OutCmd.DefaultDynamicValues.AccelerationRate := PERCENT_UINT_TO_REAL(_response.AccelerationRate , IsOptional := FALSE);
  OutCmd.DefaultDynamicValues.DecelerationRate := PERCENT_UINT_TO_REAL(_response.DecelerationRate , IsOptional := TRUE );
  OutCmd.DefaultDynamicValues.JerkRate         := PERCENT_UINT_TO_REAL(_response.JerkRate         , IsOptional := TRUE );
END_IF

