METHOD PROTECTED CheckParameterValid : BOOL
VAR_IN_OUT
  /// Robot assignment of function
  AxesGroup : AxesGroup; 
END_VAR
VAR
  /// internal index for loops
 _idx : DINT;
END_VAR

ST.xhtml:
                  CheckParameterValid := TRUE;

// Check ParCmd.ProcessingMode defined ? 
IF (( ProcessingMode < ProcessingModeEnum.BUFFERED         ) OR // ST-FIX F26
    ( ProcessingMode > ProcessingModeEnum.TRIGGER_MULTIPLE ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_DEFINED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;                          
END_IF

// Check ProcessingModea valid ? 
IF (( ProcessingMode <> ProcessingModeEnum.BUFFERED ) AND
    ( ProcessingMode <> ProcessingModeEnum.ABORTING ) AND
    ( ProcessingMode <> ProcessingModeEnum.PARALLEL ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_PROCESSINGMODE_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ProcessingMode = {1}',
                          Para1       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;
END_IF


// Check SequenceFlag valid ? 
IF (( SequenceFlag <> SequenceFlagEnum.NO_SEQUENCE        ) AND
    ( SequenceFlag <> SequenceFlagEnum.PRIMARY_SEQUENCE   ) AND
    ( SequenceFlag <> SequenceFlagEnum.SECONDARY_SEQUENCE ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_SEQFLAG_NOT_ALLOWED, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter SequenceFlag = {1}',
                          Para1       := SEQUENCE_FLAG_TO_STRING(SequenceFlag));
  RETURN;
END_IF


// Check ParCmd.ToolNo valid ? 
IF (( ParCmd.ToolNo < 0                                                  ) OR  
    ( ParCmd.ToolNo > 254                                                ) OR
    ( ParCmd.ToolNo > AxesGroup.State.ConfigurationData.HighestToolIndex ) OR
    ( ParCmd.ToolNo > AxesGroup.State.UnifiedToolIndex                   ))
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;

  // Check ToolNo available on RC ? 
  IF (( ParCmd.ToolNo > AxesGroup.State.ConfigurationData.HighestToolIndex ) AND ( ParCmd.ToolNo <= 254 )) // ST-FIX F98: outside -1..254 is a range error
  THEN
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_TOOLNO_UNAVAILABLE, Overwrite := TRUE );
  ELSE
    SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_TOOLNO_RANGE, Overwrite := TRUE );
	END_IF  

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ToolNo = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.ToolNo));
  RETURN;
END_IF


// Check ParCmd.LoadNo valid ? 
IF (( ParCmd.ToolData.LoadNo < 0   ) OR
    ( ParCmd.ToolData.LoadNo > 254 ))      
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ToolData.LoadNo = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.ToolData.LoadNo));
  RETURN;
END_IF


// Check ParCmd.ToolData.X ? 
IF ( SysDepIsValidReal(ParCmd.ToolData.X) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ToolData.X = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.ToolData.X));

  RETURN;                          
END_IF


// Check ParCmd.ToolData.Y ? 
IF ( SysDepIsValidReal(ParCmd.ToolData.Y) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ToolData.Y = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.ToolData.Y));

  RETURN;                          
END_IF


// Check ParCmd.ToolData.Z ? 
IF ( SysDepIsValidReal(ParCmd.ToolData.Z) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ToolData.Z = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.ToolData.Z));

  RETURN;                          
END_IF


// Check ParCmd.ToolData.Rx ? 
IF ( SysDepIsValidReal(ParCmd.ToolData.Rx) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ToolData.Rx = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.ToolData.Rx));

  RETURN;                          
END_IF


// Check ParCmd.ToolData.Ry ? 
IF ( SysDepIsValidReal(ParCmd.ToolData.Ry) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ToolData.Ry = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.ToolData.Ry));

  RETURN;                          
END_IF


// Check ParCmd.ToolData.Rz ? 
IF ( SysDepIsValidReal(ParCmd.ToolData.Rz) = FALSE ) 
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );

  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ToolData.Rz = {1}',
                          Para1       := VALID_REAL_TO_STRING(ParCmd.ToolData.Rz));

  RETURN;                          
END_IF


// Check ParCmd.ToolData.ID valid ? 
IF (( ParCmd.ToolData.ID < 0   ) OR
    ( ParCmd.ToolData.ID > 255 ))      
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ToolData.ID = {1}',
                          Para1       := USINT_TO_STRING(ParCmd.ToolData.ID));
  RETURN;
END_IF


// Check ParCmd.ToolData.ExternalTCP valid ? 
IF (( ParCmd.ToolData.ExternalTCP <> FALSE ) AND
    ( ParCmd.ToolData.ExternalTCP <> TRUE  ))      
THEN
  // Parameter not valid
  CheckParameterValid := FALSE;
  // Set error
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_INVALID_PAR_CMD, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara1 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter ParCmd.ToolData.ExternalTCP = {1}',
                          Para1       := BOOL_TO_STRING(ParCmd.ToolData.ExternalTCP));
  RETURN;
END_IF

// ST-FIX F69: trigger IDs and SequenceFlag (table 7-1, 5.5.12.4, e.g. table 6-496)
// ST-FIX F83: not for DEACTIVATE (it is sent with the SequenceFlag of the command it ends)
IF ( CheckParameterValid ) AND ( ProcessingMode <> ProcessingModeEnum.DEACTIVATE ) AND ( ( (( ProcessingMode = ProcessingModeEnum.BUFFERED ) OR ( ProcessingMode = ProcessingModeEnum.ABORTING ) OR ( ProcessingMode = ProcessingModeEnum.TRIGGER_BUFFERED ) OR ( ProcessingMode = ProcessingModeEnum.TRIGGER_ABORTING )) ) = ( SequenceFlag = SequenceFlagEnum.NO_SEQUENCE ) )
THEN
  CheckParameterValid := FALSE;
  SetError( ErrorID := RobotLibraryErrorIdEnum.ERR_SEQFLAG_INVALID_IN_PROC_MODE, Overwrite := TRUE );
  // Create log entry
  CreateLogMessagePara2 ( Timestamp   := AxesGroup.State.SystemTime,
                          MessageType := MessageType.CMD,
                          Severity    := Severity.ERROR,
                          MessageCode := ErrorID,
                          MessageText := 'Invalid Parameter SequenceFlag = {1} with ProcessingMode = {2}',
                          Para1       := SEQUENCE_FLAG_TO_STRING(SequenceFlag),
                          Para2       := PROCESSING_MODE_TO_STRING(ProcessingMode));
  RETURN;
END_IF

